  --token-naito-sutoka-w: var(--invocation-w);
  --token-naito-sutoka-h: var(--invocation-h);
  --token-naito-sutoka-y: 0px;
  --token-ojo-de-buho-w: 6.2%;
  --token-ojo-de-buho-h: 12.4%;
  --token-ojo-de-buho-y: 0px;
  --token-bushi-honorable-w: var(--invocation-w);
  --token-bushi-honorable-h: var(--invocation-h);
  --token-bushi-honorable-y: 0px;
  --token-samurai-akari-w: 6.2%;
  --token-samurai-akari-h: 12.4%;
  --token-samurai-akari-y: 0px;
  --token-toyotomi-hideyoshi-w: 7.4%;
  --token-toyotomi-hideyoshi-h: 14.2%;
  --token-toyotomi-hideyoshi-y: 0px;

/* ===== VALORES BASE FUENTE MÁGICA ===== */
  --fountain-p1-left: 12%;
  --fountain-p1-top: 88%;
  --fountain-p2-left: 91%;
  --fountain-p2-top: 14%;

  --fountain-size: 18%;
  --fountain-opacity: .72;
  --fountain-glow: 2;

  --fountain-particle-size:4px;
  --fountain-particle-distance: 1;
  --fountain-particle-speed: 15s;
  --fountain-particle-frequency: 4.60s;
  --fountain-particle-scale: 2;


  /* =========================================================
     ROK, VALORES BASE DE ARENA Y DOS CUADRÍCULAS
     ========================================================= */

  /* Zoom/pan interactivo con mouse:
     - Rueda del mouse sobre la arena = acercar/alejar.
     - Click sostenido + arrastrar = mover la arena cuando esté ampliada.
  */
  --board-zoom: 1;
  --board-pan-x: 0px;
  --board-pan-y: 0px;

  /* Tamaño general del tablero dentro de la pantalla */
  --board-aspect: 2 / 3;
  --board-max-width: 100%;
  --board-max-height: 100%;

  /* Imagen de arena */
  --arena-left: 0%;
  --arena-top: 0%;
  --arena-width: 100%;
  --arena-height: 100%;
  --arena-fit: cover;

  /* Arena japonesa v5.2.0: valores base para encajar sin recalibrar todo */
  --arena-adjust-x: 0%;
  --arena-adjust-y: 0%;
  --arena-adjust-scale: 1;
  --arena-adjust-origin: center center;

  /* Valores base del grid */
  --grid-left-base: 24%;
  --grid-top-base: 14%;
  --grid-width-base: 53.7%;
  --grid-height-base: 75.5%;

  /* Tamaño parejo para ambos grids */
  --grid-row-height: 35.8%;
  --risk-ally-reference-bottom: 89.5%;

  /* GRID ENEMIGO 9x9 */
  --enemy-grid-left: var(--grid-left-base);
  --enemy-grid-top: var(--grid-top-base);
  --enemy-grid-width: var(--grid-width-base);
  --enemy-grid-height: var(--grid-row-height);

  /* GRID ALIADO 9x9 */
  --ally-grid-left: var(--grid-left-base);
  --ally-grid-top: calc(var(--risk-ally-reference-bottom) - var(--grid-row-height));
  --ally-grid-width: var(--grid-width-base);
  --ally-grid-height: var(--grid-row-height);

  /* =========================================================
     VALORES VISUALES DEL GRID, SEPARADOS POR LADO

     IMPORTANTE:
     Ya no hay un solo fill opacity global.
     Ahora el enemigo y el aliado se controlan por separado.

     Los colores usan RGB sin rgba:
     rojo = 255, 255, 255
     morado = 155, 77, 255
     rojo oscuro = 198, 59, 59
  ========================================================= */

  /* GRID ENEMIGO, arriba */
  --enemy-cell-line-color: 255, 255, 255;
  --enemy-cell-line-opacity: 0.10;

  --enemy-cell-fill-color-a: 198, 59, 59;
  --enemy-cell-fill-color-b: 198, 59, 59;
  --enemy-cell-fill-opacity-a: 0.20;
  --enemy-cell-fill-opacity-b: 0.012;

  --enemy-cell-label-color: 0, 0, 0;
  --enemy-cell-label-opacity: 0.72;

  --enemy-calibration-color: 255, 255, 255;
  --enemy-calibration-opacity: 0.12;

  /* GRID ALIADO, abajo */
  --ally-cell-line-color: 255, 255, 255;
  --ally-cell-line-opacity: 0.10;

  --ally-cell-fill-color-a: 155, 77, 255;
  --ally-cell-fill-color-b: 155, 77, 255;
  --ally-cell-fill-opacity-a: 0.20;
  --ally-cell-fill-opacity-b: 0.12;

  --ally-cell-label-color: 0, 0, 0;
  --ally-cell-label-opacity: 0.72;

  --ally-calibration-color: 255, 255, 255;
  --ally-calibration-opacity: 0.12;

  /* Hover general de casillas */
  --cell-hover-opacity: 0.18;

  /* =========================================================
     LÍNEAS DE ZONA DE RIESGO Y LÍNEA CENTRAL
     ========================================================= */

  --risk-thickness: 4px;
  --risk-line-opacity: 0.62;
  --risk-line-glow-opacity: 0.72;

  --risk-enemy-left: var(--enemy-grid-left);
  --risk-enemy-top: var(--enemy-grid-top);
  --risk-enemy-width: var(--enemy-grid-width);

  --risk-ally-left: var(--ally-grid-left);
  --risk-ally-top: calc(var(--ally-grid-top) + var(--ally-grid-height));
  --risk-ally-width: var(--ally-grid-width);

  /* Línea central */
  --battle-center-left: var(--grid-left-base);
  --battle-center-top-offset: -0.5%;
  --battle-center-top: calc(((var(--enemy-grid-top) + var(--enemy-grid-height) + var(--ally-grid-top)) / 2) + var(--battle-center-top-offset));
  --battle-center-width: var(--grid-width-base);
  --battle-center-thickness: 4px;
  --battle-center-opacity: 0.78;
  --battle-center-glow-opacity: 0.78;

  /* =========================================================
     TAMAÑO Y AJUSTE VISUAL DE FICHAS
     ========================================================= */

  --caster-w: 5%;
  --caster-h: 11%;
  --caster-offset-x: 0px;
  --caster-offset-y: 0px;

  /* KASTERS · valores individuales de token */
  --token-caster-hanzo-w: var(--caster-w);
  --token-caster-hanzo-h: var(--caster-h);
  --token-caster-hanzo-x: 0px;
  --token-caster-hanzo-y: 0px;
  --token-caster-tokugawa-w: var(--caster-w);
  --token-caster-tokugawa-h: var(--caster-h);
  --token-caster-tokugawa-x: 0px;
  --token-caster-tokugawa-y: 0px;

  --guardian-w: 6%;
  --guardian-h: 11%;
  --guardian-offset-x: 0px;
  --guardian-offset-y: 0px;

  --invocation-w: 5%;
  --invocation-h: 10%;
  --invocation-offset-x: 0px;
  --invocation-offset-y: 0px;

  /* =========================================================
     PALETA GENERAL
     ========================================================= */

  --bg: #060607;
  --panel: #0c0c0f;
  --panel-2: #141419;
  --line: #2c2c34;
  --text: #e8e2d8;
  --muted: #958d9b;
  --p1: #9b4dff;
  --p1-soft: rgba(155, 77, 255, .28);
  --p2: #c63b3b;
  --p2-soft: rgba(198, 59, 59, .25);
  --cyan: #26eaff;
  --gold: #c59a42;
  --cell-border: rgba(54, 255, 229, .22);
  --cell-label-font-size: 5px;

  /* =========================================================
     VALORES BADGES / INDICADORES EN ARENA - v5.1.3
     ========================================================= */

  /* Guardianes: resistencia */

  /* Invocaciones: posición general del grupo abajo de la ficha */
  --invocation-badges-x: 0px;
  --invocation-badges-y: -7px;

  /* Invocaciones: badge completo de daño */
  --damage-badge-x: -16px;
  --damage-badge-y: -35px;
  --damage-badge-box-size: 40px;

  /* Invocaciones: SVG del arma/daño */
  --damage-icon-size: 10px;
  --damage-icon-x: 10px;
  --damage-icon-y: -8px;

  /* Invocaciones: número de daño */
  --damage-number-size: 14px;
  --damage-number-font-size: 10px;
  --damage-number-bg: #ffffff;
  --damage-number-color: #12071e;
  --damage-number-x: 22px;
  --damage-number-y: 16px;

  /* Invocaciones: badge completo de vida */
  --life-badge-x: 16px;
  --life-badge-y: -35px;
  --life-badge-box-size: 40px;

  /* Invocaciones: corazón */
  --life-icon-size: 12px;
  --life-icon-x: -9.5px;
  --life-icon-y: -8px;

  /* Invocaciones: número de vida */
  --life-number-size: 14px;
  --life-number-font-size: 10px;
  --life-number-bg: #ffffff;
  --life-number-color: #12071e;
  --life-number-x: 4px;
  --life-number-y: 16px;
}


* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  margin: 0;
  background: radial-gradient(circle at 50% 20%, #16101f, var(--bg) 55%);
  color: var(--text);
  font-family: Georgia, 'Times New Roman', serif;
  overflow: hidden;
}

button {
  font-family: inherit;
}

.game-shell {
  height: 100vh;
  width: 100vw;
  display: grid;
  grid-template-columns: 132px minmax(430px, 1fr) 150px 440px;
  grid-template-rows: 64px 1fr 76px;
  gap: 8px;
  padding: 8px;
}

.panel,
.top-bar {
  background: linear-gradient(180deg, rgba(19, 19, 23, .97), rgba(6, 6, 7, .97));
  border: 1px solid var(--line);
  box-shadow: inset 0 0 18px rgba(0, 0, 0, .65), 0 0 18px rgba(0, 0, 0, .45);
}

.top-bar {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 440px 1fr 170px;
  align-items: center;
  padding: 6px;
  gap: 14px;
}

.phase-boxes {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.phase-box {
  height: 48px;
  border: 1px solid #363642;
  background: #0b0b0d;
  display: flex;
  align-items: center;
  justify-content: center;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #8e8790;
  position: relative;
}

.phase-box.active.p1 {
  color: white;
  background: linear-gradient(180deg, #1d102c, #0d0a12);
  border-color: var(--p1);
  box-shadow: inset 0 -4px 0 var(--p1), 0 0 14px var(--p1-soft);
}

.phase-box.active.p2 {
  color: white;
  background: linear-gradient(180deg, #2b1010, #120a0a);
  border-color: var(--p2);
  box-shadow: inset 0 -4px 0 var(--p2), 0 0 14px var(--p2-soft);
}

.phase-box.waiting::after {
  content: none;
}

.turn-banner {
  text-align: center;
  font-size: 26px;
  letter-spacing: 4px;
  text-transform: uppercase;
}

.main-button {
  height: 46px;
  background: #15151b;
  color: var(--text);
  border: 1px solid #484852;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.main-button:hover {
  border-color: var(--p1);
  box-shadow: 0 0 12px var(--p1-soft);
}

.left-panel {
  grid-column: 1;
  grid-row: 2;
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.player-block {
  text-align: center;
  border-bottom: 1px solid var(--line);
  padding-bottom: 12px;
}

.player-mark {
  font-size: 42px;
  color: var(--p1);
  text-shadow: 0 0 18px var(--p1);
}

h2,
h3,
p {
  margin: 0;
}

.player-block h2 {
  color: #c9a6ff;
  text-transform: uppercase;
  font-size: 18px;
  margin-bottom: 10px;
}

.player-block p {
  font-family: Arial, sans-serif;
  font-size: 13px;
  color: #c8c0ce;
  margin: 8px 0;
}

.hint-card {
  background: rgba(255, 255, 255, .03);
  border: 1px solid #292934;
  padding: 8px;
}

.hint-card h3 {
  font-size: 12px;
  text-transform: uppercase;
  color: #b7adbf;
  text-align: center;
  margin-bottom: 8px;
}

.hint-card small {
  display: block;
  font-family: Arial, sans-serif;
  color: var(--muted);
  text-align: center;
  margin-top: 8px;
  font-size: 10px;
}

.mini-keypad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
}

.mini-keypad span {
  min-height: 22px;
  display: grid;
  place-items: center;
  background: #111116;
  border: 1px solid #3b3b45;
  font-family: Arial, sans-serif;
  font-size: 12px;
}

.board-panel {
  grid-column: 2;
  grid-row: 2;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: visible;
}

.board {
  position: relative;
  height: var(--board-max-height);
  aspect-ratio: var(--board-aspect);
  max-width: var(--board-max-width);
  background: #050505;
  overflow: visible;
  cursor: grab;
  touch-action: none;
}

.board-content {
  position: absolute;
  inset: 0;
  transform: translate(var(--board-pan-x), var(--board-pan-y)) scale(var(--board-zoom));
  transform-origin: center center;
}

.arena-img {
  position: absolute;
  left: calc(var(--arena-left) + var(--arena-adjust-x));
  top: calc(var(--arena-top) + var(--arena-adjust-y));
  width: var(--arena-width);
  height: var(--arena-height);
  object-fit: var(--arena-fit);
  transform: scale(var(--arena-adjust-scale));
  transform-origin: var(--arena-adjust-origin);
}

.grid-layer {
  position: absolute;
  display: grid;
  grid-template-columns: repeat(9, 1fr);
  grid-template-rows: repeat(9, 1fr);
  z-index: 3;
}

.enemy-grid {
  left: var(--enemy-grid-left);
  top: var(--enemy-grid-top);
  width: var(--enemy-grid-width);
  height: var(--enemy-grid-height);
}

.ally-grid {
  left: var(--ally-grid-left);
  top: var(--ally-grid-top);
  width: var(--ally-grid-width);
  height: var(--ally-grid-height);
}

.cell {
  appearance: none;
  -webkit-appearance: none;
  margin: 0;
  width: 100%;
  height: 100%;
  position: relative;
  font-family: Arial, sans-serif;
  font-size: var(--cell-label-font-size);
  text-align: left;
  padding: 0;
  background: transparent;
  text-shadow: 0 1px 1px rgba(255, 255, 255, .28);
}

.cell-label {
  position: absolute;
  top: 1px;
  left: 2px;
  pointer-events: none;
  user-select: none;
  line-height: 1;
  font-weight: 700;
}

/* =========================================================
   VISUAL DEL GRID ENEMIGO, SEPARADO POR LADO
   ========================================================= */

.enemy-grid .cell {
  border: 1px solid rgba(var(--enemy-cell-line-color), var(--enemy-cell-line-opacity));
  outline: 1px solid rgba(var(--enemy-calibration-color), var(--enemy-calibration-opacity));
  color: rgba(var(--enemy-cell-label-color), var(--enemy-cell-label-opacity));
}

.enemy-grid .cell:nth-child(odd) {
  background: rgba(var(--enemy-cell-fill-color-a), var(--enemy-cell-fill-opacity-a));
}

.enemy-grid .cell:nth-child(even) {
  background: rgba(var(--enemy-cell-fill-color-b), var(--enemy-cell-fill-opacity-b));
}

/* =========================================================
   VISUAL DEL GRID ALIADO, SEPARADO POR LADO
   ========================================================= */

.ally-grid .cell {
  border: 1px solid rgba(var(--ally-cell-line-color), var(--ally-cell-line-opacity));
  outline: 1px solid rgba(var(--ally-calibration-color), var(--ally-calibration-opacity));
  color: rgba(var(--ally-cell-label-color), var(--ally-cell-label-opacity));
}

.ally-grid .cell:nth-child(odd) {
  background: rgba(var(--ally-cell-fill-color-a), var(--ally-cell-fill-opacity-a));
}

.ally-grid .cell:nth-child(even) {
  background: rgba(var(--ally-cell-fill-color-b), var(--ally-cell-fill-opacity-b));
}

.cell.ally {
  box-shadow: none;
}

.cell.enemy {
  box-shadow: none;
}

.cell:hover {
  background: rgba(38, 234, 255, var(--cell-hover-opacity));
}

.cell.caster-zone {
  background: rgba(155, 77, 255, .22);
  cursor: pointer;
  animation: pulseCell 1s infinite alternate;
}

.cell.selected-place {
  background: rgba(255, 255, 255, .25);
  outline: 2px solid #fff;
}

.cell.occupied {
  pointer-events: none;
}

@keyframes pulseCell {
  from {
    box-shadow: inset 0 0 10px rgba(155, 77, 255, .2);
  }

  to {
    box-shadow: inset 0 0 24px rgba(155, 77, 255, .55);
  }
}

.units-layer {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
}

.unit {
  position: absolute;
  transform: translate(-50%, -86%);
  display: grid;
  place-items: end center;
  filter: drop-shadow(0 18px 10px rgba(0, 0, 0, .55));
}

.unit img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}

.unit.caster {
  width: var(--caster-w);
  height: var(--caster-h);
  transform: translate(calc(-50% + var(--caster-offset-x)), calc(-86% + var(--caster-offset-y)));
}

.unit.guardian {
  width: var(--guardian-w);
  height: var(--guardian-h);
  transform: translate(calc(-50% + var(--guardian-offset-x)), calc(-80% + var(--guardian-offset-y)));
}

.unit.invocation {
  width: var(--invocation-w);
  height: var(--invocation-h);
  transform: translate(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y)));
}

.unit-label {
  display: none;
}

.arena-line {
  position: absolute;
  z-index: 4;
  border-radius: 999px;
  pointer-events: none;
}

.risk-line {
  height: var(--risk-thickness);
  opacity: var(--risk-line-opacity);
}

.risk-line-enemy {
  left: var(--risk-enemy-left);
  top: var(--risk-enemy-top);
  width: var(--risk-enemy-width);
  background: var(--p2);
  box-shadow:
    0 0 10px rgba(198, 59, 59, var(--risk-line-glow-opacity)),
    0 0 26px rgba(198, 59, 59, var(--risk-line-glow-opacity));
}

.risk-line-ally {
  left: var(--risk-ally-left);
  top: var(--risk-ally-top);
  width: var(--risk-ally-width);
  background: var(--p1);
  box-shadow:
    0 0 10px rgba(155, 77, 255, var(--risk-line-glow-opacity)),
    0 0 26px rgba(155, 77, 255, var(--risk-line-glow-opacity));
}

.battle-center-line {
  left: var(--battle-center-left);
  top: var(--battle-center-top);
  width: var(--battle-center-width);
  height: var(--battle-center-thickness);
  opacity: var(--battle-center-opacity);
  background: var(--p1);
  box-shadow:
    0 0 12px rgba(155, 77, 255, var(--battle-center-glow-opacity)),
    0 0 32px rgba(155, 77, 255, var(--battle-center-glow-opacity));
}

.board-content.player-p2 .battle-center-line {
  background: var(--p2);
  box-shadow:
    0 0 12px rgba(198, 59, 59, var(--battle-center-glow-opacity)),
    0 0 32px rgba(198, 59, 59, var(--battle-center-glow-opacity));
}

.board-content.player-p1 .battle-center-line {
  background: var(--p1);
  box-shadow:
    0 0 12px rgba(155, 77, 255, var(--battle-center-glow-opacity)),
    0 0 32px rgba(155, 77, 255, var(--battle-center-glow-opacity));
}

.cast-panel {
  grid-column: 3;
  grid-row: 2;
  padding: 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

.cast-panel h3 {
  text-transform: uppercase;
  font-size: 15px;
  color: #cfc7da;
}

.cast-queue {
  width: 100%;
  min-height: 280px;
  display: flex;
  flex-direction: column;
  gap: var(--player-cast-token-distance-y) !important;
  align-items: center;
}

/* Mi zona de kasteo · ACERCAMIENTO EXTRA ENTRE TOKENS COMPLETOS · permite valores negativos */
.cast-panel .cast-queue > .cast-item + .cast-item {
  margin-top: var(--player-cast-token-overlap-y) !important;
}


.cast-item {
  width: 100px;
  height: 138px;
  position: relative;
  border: 1px solid #443b50;
  background: #08080a;
}

.cast-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.cast-badge {
  position: absolute;
  right: -10px;
  bottom: -10px;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #12071e;
  border: 2px solid var(--p1);
  color: white;
  font: bold 18px Arial;
  box-shadow: 0 0 12px var(--p1);
}

.small-note {
  font: 11px Arial;
  color: var(--muted);
  text-align: center;
}

.right-panel {
  grid-column: 4;
  grid-row: 2;
  padding: 10px;
  display: grid;
  grid-template-rows: 36px 1fr 182px;
  gap: 10px;
}

.tab-stack {
  display: flex;
  align-items: end;
  gap: 4px;
}

.deck-tab {
  flex: 1;
  height: 34px;
  background: #111116;
  color: #a39da9;
  border: 1px solid #34343b;
  cursor: pointer;
  text-transform: uppercase;
}

.deck-tab.active {
  background: linear-gradient(180deg, #211135, #0f0d14);
  color: white;
  border-color: var(--p1);
  box-shadow: inset 0 -3px 0 var(--p1);
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(4, 1fr);
  gap: 8px;
  min-height: 0;
}

.card-slot {
  position: relative;
  background: linear-gradient(180deg, #101014, #070708);
  border: 1px solid #33333c;
  box-shadow: inset 0 0 24px rgba(0, 0, 0, .7);
  cursor: pointer;
  min-height: 0;
}

.card-slot.empty::before {
  content: '✦';
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: rgba(255, 255, 255, .08);
  font-size: 38px;
}

.key-label {
  position: absolute;
  z-index: 4;
  right: 4px;
  bottom: 4px;
  background: rgba(0, 0, 0, .8);
  border: 1px solid #50505a;
  color: white;
  min-width: 22px;
  text-align: center;
  font: 12px Arial;
  padding: 2px 3px;
}

.card-slot.selected {
  border-color: #fff;
  box-shadow: 0 0 20px var(--p1-soft), inset 0 0 14px rgba(255, 255, 255, .18);
}

.card {
  position: absolute;
  inset: 4px;
  overflow: hidden;
}

.card-layer {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.card-bg {
  object-fit: cover;
  z-index: 1;
}

.card-art {
  object-fit: contain;
  z-index: 2;
  transform: scale(1.12) translateY(9%);
  filter: drop-shadow(0 9px 8px rgba(0, 0, 0, .75));
}

.card-skin {
  object-fit: fill;
  z-index: 3;
  pointer-events: none;
}


.card-domain-zone {
  position: absolute;
  top: var(--domain-zone-top, 6px);
  right: var(--domain-zone-right, 6px);
  width: var(--domain-zone-width, 34%);
  height: var(--domain-zone-height, 23%);
  pointer-events: none;
}
.card-domain-layer {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  pointer-events: none;
}
.card-domain-element {
  transform: translateY(var(--domain-element-offset-y, 0px));
}
.card-domain-attribute {
  width: var(--domain-attribute-width, 44%);
  height: var(--domain-attribute-height, 62%);
  left: 50%;
  top: 50%;
  transform: translate(-50%, calc(-50% + var(--domain-attribute-offset-y, 2px)));
  filter: drop-shadow(0 0 4px rgba(0,0,0,.45));
}


/* =========================================================
   ROK v5.3.14 · DOMINIO SOLO EN VIEW/MODAL DE CARTA
   ========================================================= */
.card-info-preview .card-domain-zone {
  position: absolute;
  left: 150px;
  top: -20px;
  width: 66px;
  height: 58px;
  pointer-events: none;
  overflow: visible;
  z-index: 5;
}
.card-info-preview .card-domain-layer {
  position: absolute;
  left: 50%;
  top: 50%;
  object-fit: contain;
  pointer-events: none;
  user-select: none;
}
.card-info-preview .card-domain-bg {
  width: 43px;
  height: 43px;
  transform: translate(calc(-50% + 0px), calc(-50% + 0px));
  z-index: 1;
  opacity: .72;
  background: rgba(0, 0, 0, .78);
  border: 1px solid rgba(255, 255, 255, .42);
  border-radius: 50%;
  box-shadow: 0 0 8px rgba(255,255,255,.18), inset 0 0 12px rgba(255,255,255,.08);
}
.card-info-preview .card-domain-element {
  width: 72px;
  height: 72px;
  transform: translate(calc(-50% + -3.5px), calc(-50% + -5px));
  z-index: 2;
}
.card-info-preview .card-domain-attribute {
  width: 36px;
  height: 36px;
  transform: translate(calc(-50% + 0px), calc(-50% + 5px));
  z-index: 3;
  filter: drop-shadow(0 0 4px rgba(0,0,0,.55));
}

.card-cost {
  position: absolute;
  z-index: 4;
  left: 5px;
  top: 5px;
  background: var(--p1);
  color: white;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font: bold 14px Arial;
  box-shadow: 0 0 10px var(--p1);
}

.caster-stats {
  border: 1px solid #353540;
  background: #09090c;
  display: grid;
  grid-template-columns: 44% 1fr;
  overflow: hidden;
}

.caster-portrait-wrap {
  position: relative;
  overflow: hidden;
  background: #050505;
}

.caster-portrait-wrap img {
  position: absolute;
  width: 155%;
  left: -32%;
  bottom: -30%;
  filter: drop-shadow(0 0 12px var(--p1));
}

.caster-info {
  padding: 10px;
}

.caster-info h2 {
  font-size: 20px;
  color: #dec8ff;
  margin-bottom: 2px;
}

.tag {
  font: 12px Arial;
  color: #bcb3c8;
  letter-spacing: 2px;
}

.stats-line {
  display: grid;
  grid-template-columns: 1fr 58px;
  gap: 8px;
  align-items: center;
  border-top: 1px solid #24242c;
  padding: 7px 0;
  font-family: Arial, sans-serif;
}

.stats-line:first-of-type {
  margin-top: 12px;
}

.stats-line strong {
  text-align: center;
  background: #101014;
  border: 1px solid #343440;
  padding: 4px;
  color: white;
}

.bottom-bar {
  grid-column: 1 / -1;
  grid-row: 3;
  display: grid;
  grid-template-columns: 180px 1fr 420px;
  gap: 12px;
  align-items: center;
  padding: 8px 14px;
}

.resource-title {
  text-transform: uppercase;
  color: #bdb5c8;
  font-size: 14px;
  letter-spacing: 1px;
}

.resource-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.orb {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, .35);
  background: radial-gradient(circle at 34% 30%, #fff, var(--orb-color) 20%, #100016 61%, #050308 100%);
  box-shadow: 0 0 18px var(--orb-color);
  position: relative;
}

.orb::after {
  content: attr(data-type);
  position: absolute;
  left: 55px;
  top: 13px;
  font: 12px Arial;
  color: #e5dced;
  white-space: nowrap;
}


/* Recursos elementales permanentes: reemplazan los orbes temporales por gotas reales. */
.orb.resource-token {
  width: 46px;
  height: 46px;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  display: grid;
  place-items: center;
  overflow: visible;
}
.orb.resource-token img {
  width: 54px;
  height: 54px;
  object-fit: contain;
  filter: drop-shadow(0 0 calc(16px * .72) var(--orb-color, #fff));
  pointer-events: none;
}
.orb.resource-token::after {
  left: calc(46px + 9px);
}
.extract-resource-fx {
  width: 54px;
  height: 54px;
  transform: translate(-50%, -50%);
  filter: drop-shadow(0 0 18px var(--resource-color, #fff));
}
.extract-resource-fx img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  pointer-events: none;
}
.enemy-mini-resource-token {
  background: transparent !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  display: grid;
  place-items: center;
  overflow: visible;
}
.enemy-mini-resource-token img {
  width: 20px;
  height: 20px;
  object-fit: contain;
  filter: drop-shadow(0 0 6px var(--orb-color, #fff));
}

.system-log {
  font: 13px Arial;
  color: #d7cce5;
  background: #09090c;
  border: 1px solid #2d2d36;
  min-height: 42px;
  padding: 10px;
  overflow: hidden;
}

.transition-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, .55);
  z-index: 99;
  display: grid;
  place-items: center;
  pointer-events: none;
  opacity: 0;
  transition: opacity .25s ease;
}

.transition-overlay.show {
  opacity: 1;
}

.transition-card {
  min-width: 520px;
  padding: 26px 42px;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 5px;
  font-size: 30px;
  border: 1px solid var(--p1);
  background: linear-gradient(180deg, #141018, #050506);
  box-shadow: 0 0 28px var(--p1-soft), inset 0 0 20px rgba(255, 255, 255, .05);
}

.transition-card.p2 {
  border-color: var(--p2);
  box-shadow: 0 0 28px var(--p2-soft), inset 0 0 20px rgba(255, 255, 255, .05);
}

@media (max-width: 1200px) {
  .game-shell {
    grid-template-columns: 110px minmax(360px, 1fr) 120px 360px;
  }

  .turn-banner {
    font-size: 20px;
  }
}

