/* =========================================================
   ROK BETA v0.12: INTERACCIÓN DE ARENA
   - Click izquierdo queda libre para casillas y fichas.
   - Arrastre/pan solo con botón central del mouse.
   ========================================================= */

.board {
  cursor: default !important;
}

.board.is-panning {
  cursor: grabbing !important;
}

.grid-layer {
  pointer-events: auto !important;
}

.cell {
  cursor: pointer;
}

.cell.occupied {
  pointer-events: auto !important;
  cursor: pointer;
}

.units-layer {
  pointer-events: none;
}

