}

.caster-wide-card .card-layer {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.caster-wide-card .card-bg {
  object-fit: cover !important;
}

.caster-wide-art {
  object-fit: contain !important;
