}

.caster-wide-card .card-skin {
  object-fit: fill !important;
  pointer-events: none;
}

/* Textos distribuidos dentro del contenedor ancho. */
.caster-wide-info {
  min-width: 0;
  height: 100%;
  display: grid;
  grid-template-rows: auto 1fr;
  align-content: center;
  gap: 12px;
}

.caster-wide-title h2 {
  font-size: 28px;
  color: #dec8ff;
  margin: 0 0 4px;
  letter-spacing: 1px;
}

.caster-wide-title .tag {
