/* =========================================================
   ROK BETA v0.14: PROPORCIÓN POR SKIN + FLUJO MOUSE DE KASTEO
   ========================================================= */

:root {
  /* El skin manda la proporción de TODAS las cartas.
     Tamaño real detectado del skin actual: 1595 x 1595. */
  --card-skin-aspect: 1595 / 1595;
  --kaster-panel-height: 110px;
}

/* Panel Kaster: misma ubicación horizontal de v0.13 corregida,
   pero altura reducida aproximadamente al 50%. */
.game-shell {
  grid-template-rows: minmax(0, 1fr) var(--kaster-panel-height) !important;
}

.caster-wide-panel {
  min-height: var(--kaster-panel-height) !important;
  max-height: var(--kaster-panel-height) !important;
  grid-template-columns: 88px minmax(0, 1fr) !important;
  gap: 10px !important;
  padding: 7px 10px !important;
}

.caster-wide-card {
  aspect-ratio: var(--card-skin-aspect) !important;
  height: 92px !important;
  width: auto !important;
  max-width: 92px !important;
  max-height: 92px !important;
}

.caster-wide-title h2 {
  font-size: 18px !important;
  margin-bottom: 0 !important;
}

.caster-wide-title .tag {
  font-size: 10px !important;
}

.caster-wide-info {
  gap: 5px !important;
}

.caster-wide-stats {
  grid-template-columns: repeat(4, minmax(62px, 1fr)) !important;
  gap: 5px !important;
}

.caster-wide-stats .stats-line {
  padding: 4px 6px !important;
  gap: 3px !important;
}

.caster-wide-stats .stats-line span {
  font-size: 9px !important;
}

.caster-wide-stats .stats-line strong {
  font-size: 10px !important;
  padding: 3px !important;
}

/* Las cartas del Spellbook respetan la proporción del skin. */
.card-slot {
  aspect-ratio: var(--card-skin-aspect) !important;
  min-height: unset !important;
}

.card-grid {
  grid-auto-rows: auto !important;
  align-content: start !important;
}

.card {
  aspect-ratio: var(--card-skin-aspect) !important;
}

.card-layer {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.card-bg {
  object-fit: cover !important;
}

.card-art {
  object-fit: contain !important;
}

.card-skin {
  object-fit: fill !important;
