/* =========================================================
   v0.30A · SISTEMA VISUAL DE FUENTES
   ========================================================= */
.fountain-p1 {
  left: var(--fountain-p1-left) !important;
  top: var(--fountain-p1-top) !important;
}
.fountain-p2 {
  left: var(--fountain-p2-left) !important;
  top: var(--fountain-p2-top) !important;
}

.fountain-fx {
  position: absolute;
  width: var(--fountain-size);
  aspect-ratio: 1;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 2;
  overflow: visible;
  --fountain-color: #9b4dff;
}
.fountain-fx::before {
  content: '';
  position: absolute;
  inset: 14%;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 34%,
      rgba(255,255,255,.55) 0,
      color-mix(in srgb, var(--fountain-color) 48%, white 52%) 14%,
      color-mix(in srgb, var(--fountain-color) 35%, transparent 65%) 35%,
      rgba(0,0,0,0) 72%),
    conic-gradient(from 0deg,
      color-mix(in srgb, var(--fountain-color) 28%, transparent 72%),
      rgba(255,255,255,.05),
      color-mix(in srgb, var(--fountain-color) 28%, transparent 72%));
  filter: blur(1.1px) drop-shadow(0 0 calc(22px * var(--fountain-glow)) var(--fountain-color));
  opacity: var(--fountain-opacity);
  animation: fountainSwirl 7.5s linear infinite, fountainPulse 2.8s ease-in-out infinite;
}
.fountain-fx::after {
  content: '';
  position: absolute;
  inset: 23%;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--fountain-color) 32%, white 18%);
  box-shadow: 0 0 calc(24px * var(--fountain-glow)) var(--fountain-color), inset 0 0 10px rgba(255,255,255,.08);
  opacity: calc(var(--fountain-opacity) * .55);
  animation: fountainRingPulse 2.4s ease-in-out infinite;
}
.fountain-particles {
  position: absolute;
  inset: 0;
}
.fountain-particle {
  position: absolute;
  left: 50%;
  top: 54%;
  width: var(--fountain-particle-size);
  height: var(--fountain-particle-size);
  margin-left: calc(var(--fountain-particle-size) / -2);
  margin-top: calc(var(--fountain-particle-size) / -2);
  border-radius: 50%;
  background: radial-gradient(circle,
    rgba(255,255,255,.95) 0,
    color-mix(in srgb, var(--fountain-color) 34%, white 66%) 34%,
    color-mix(in srgb, var(--fountain-color) 55%, transparent 45%) 68%,
    rgba(0,0,0,0) 100%);
  opacity: 0;
  animation: fountainParticle var(--fountain-particle-speed) ease-in-out infinite;
}
.fountain-particle.p1 { --dx: -18px; --dy: -26px; --s: .8; animation-delay: calc(var(--fountain-particle-frequency) * 0); }
.fountain-particle.p2 { --dx: 16px; --dy: -34px; --s: 1; animation-delay: calc(var(--fountain-particle-frequency) * 1); }
.fountain-particle.p3 { --dx: -28px; --dy: -18px; --s: .65; animation-delay: calc(var(--fountain-particle-frequency) * 2); }
.fountain-particle.p4 { --dx: 24px; --dy: -22px; --s: .9; animation-delay: calc(var(--fountain-particle-frequency) * 3); }
.fountain-particle.p5 { --dx: -10px; --dy: -40px; --s: .72; animation-delay: calc(var(--fountain-particle-frequency) * 4); }
.fountain-particle.p6 { --dx: 6px; --dy: -28px; --s: .6; animation-delay: calc(var(--fountain-particle-frequency) * 5); }
.fountain-particle.p7 { --dx: -22px; --dy: -36px; --s: .88; animation-delay: calc(var(--fountain-particle-frequency) * 6); }
.fountain-particle.p8 { --dx: 20px; --dy: -30px; --s: .75; animation-delay: calc(var(--fountain-particle-frequency) * 7); }

@keyframes fountainSwirl {
  from { transform: rotate(0deg) scale(1); }
  50% { transform: rotate(180deg) scale(1.04); }
  to { transform: rotate(360deg) scale(1); }
}
@keyframes fountainPulse {
  0%, 100% { opacity: calc(var(--fountain-opacity) * .8); }
  50% { opacity: var(--fountain-opacity); }
}
@keyframes fountainRingPulse {
  0%, 100% { transform: scale(.92); opacity: calc(var(--fountain-opacity) * .25); }
  50% { transform: scale(1.06); opacity: calc(var(--fountain-opacity) * .7); }
}
@keyframes fountainParticle {
  0% {
    transform: translate(0, 0) scale(.35);
    opacity: 0;
  }
  20% {
    opacity: .9;
  }
  65% {
    transform:
      translate(
        calc(var(--dx) * var(--fountain-particle-distance)),
        calc(var(--dy) * var(--fountain-particle-distance))
      )
      scale(calc(var(--s) * var(--fountain-particle-scale)));
    opacity: .72;
  }
  100% {
    transform:
      translate(
        calc(var(--dx) * var(--fountain-particle-distance) * 1.15),
        calc(var(--dy) * var(--fountain-particle-distance) * 1.15)
      )
      scale(.3);
    opacity: 0;
  }
}


.fountain-fx .fountain-gen-glow {
  position: absolute;
  inset: 8%;
  border-radius: 50%;
  background: radial-gradient(circle,
    rgba(255,255,255,.75) 0%,
    color-mix(in srgb, var(--fountain-color) 60%, white 40%) 22%,
    color-mix(in srgb, var(--fountain-color) 50%, transparent 50%) 52%,
    rgba(0,0,0,0) 76%);
  opacity: 0;
  transform: scale(.55);
  filter: blur(1.2px) drop-shadow(0 0 14px var(--fountain-color));
  transition: opacity .18s ease, transform .22s ease;
  pointer-events: none;
}

.fountain-fx.is-extracting {
  --fountain-particle-scale: var(--fountain-extract-particle-scale);
}

.fountain-fx.is-extracting::before {
  opacity: var(--fountain-extract-opacity);
  animation-duration: 2s, 1s;
}

.fountain-fx.is-extracting::after {
  opacity: calc(var(--fountain-extract-opacity) * .8);
  box-shadow: 0 0 calc(34px * var(--fountain-extract-glow)) var(--fountain-color), inset 0 0 14px rgba(255,255,255,.12);
  animation-duration: 1.1s;
}

.fountain-fx.is-extracting .fountain-particle {
  animation-duration: var(--fountain-extract-speed);
}

.fountain-fx.is-extracting .fountain-gen-glow {
  opacity: .95;
  transform: scale(1.06);
}


