/* =========================================================
   ROK v5.3.6.3 · ICONO SVG DE RESTAURACIÓN / ENFRIAMIENTO
   ========================================================= */
:root {
  /* Restauración sobre ficha */
  --restore-badge-x: 0px;
  --restore-badge-y: 10px;
  --restore-badge-icon-size: 15px;
  --restore-badge-number-size: 13px;
  --restore-badge-number-font-size: 9px;
  --restore-badge-number-x: 13px;
  --restore-badge-number-y: 10px;

  /* Icono de tiempo en casteo/respawn */
  --cooldown-time-icon-size: 23px;
  --cooldown-time-number-size: 16px;
  --cooldown-time-number-font-size: 10px;
  --cooldown-time-number-x: -3px;
  --cooldown-time-number-y: -3px;
}

/* La restauración ya no usa cápsula con fondo. Queda como icono plano + número. */
.restore-badge {
  position: absolute !important;
  right: auto !important;
  bottom: auto !important;
  left: 50% !important;
  top: 0 !important;
  width: var(--restore-badge-icon-size) !important;
  height: var(--restore-badge-icon-size) !important;
  min-width: 0 !important;
  min-height: 0 !important;
  padding: 0 !important;
  display: block !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  transform: translate(calc(-50% + var(--restore-badge-x)), var(--restore-badge-y)) !important;
  pointer-events: none !important;
  z-index: 16 !important;
}

.restore-cooldown-icon {
  position: absolute !important;
  inset: 0 !important;
  width: var(--restore-badge-icon-size) !important;
  height: var(--restore-badge-icon-size) !important;
  object-fit: contain !important;
  display: block !important;
  filter: none !important;
  box-shadow: none !important;
  border: 0 !important;
  outline: 0 !important;
  background: transparent !important;
}

.restore-cooldown-number {
  position: absolute !important;
  left: var(--restore-badge-number-x) !important;
  top: var(--restore-badge-number-y) !important;
  width: var(--restore-badge-number-size) !important;
  height: var(--restore-badge-number-size) !important;
  border-radius: 50% !important;
  display: grid !important;
  place-items: center !important;
  background: #ffffff !important;
  color: #12071e !important;
  border: 1px solid #12071e !important;
  font: 900 var(--restore-badge-number-font-size) Arial, sans-serif !important;
  line-height: 1 !important;
  box-shadow: 0 0 7px rgba(255,255,255,.62) !important;
}

/* Icono de tiempo en cast queue y respawn: mismo SVG, plano, sin cápsula de fondo. */
.cooldown-time-badge {
  position: relative !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: transparent !important;
  overflow: visible !important;
}

.cooldown-time-icon {
  width: var(--cooldown-time-icon-size) !important;
  height: var(--cooldown-time-icon-size) !important;
  object-fit: contain !important;
  display: block !important;
  filter: none !important;
  box-shadow: none !important;
  outline: 0 !important;
  border: 0 !important;
  background: transparent !important;
}

.cooldown-time-badge .cast-corner-number {
  right: var(--cooldown-time-number-x) !important;
  bottom: var(--cooldown-time-number-y) !important;
  width: var(--cooldown-time-number-size) !important;
  height: var(--cooldown-time-number-size) !important;
  font-size: var(--cooldown-time-number-font-size) !important;
}

/* Ajuste extra para que los relojes de casteo no bajen contra los badges de daño/vida. */
.cast-status,
.spawn-status {
  transform: translateY(-4px);
}


