  40%  { transform: translate(calc(-50% + var(--invocation-offset-x) + 4px), calc(-80% + var(--invocation-offset-y))) scale(1.03); }
  50%  { transform: translate(calc(-50% + var(--invocation-offset-x) - 3px), calc(-80% + var(--invocation-offset-y))) scale(1.02); }
  60%  { transform: translate(calc(-50% + var(--invocation-offset-x) + 3px), calc(-80% + var(--invocation-offset-y))) scale(1.02); }
  100% { transform: translate(calc(-50% + var(--invocation-offset-x)), calc(-80% + var(--invocation-offset-y))) scale(1); }
}


