  --bushi-armor-f-x: 0px;
  --bushi-armor-f-y: 0px;
  --bushi-armor-f-scale: 1;
  --bushi-armor-f-size: 17px;
}

.card-info-defense-factor-wrap.card-defense-factor-card-samuraibushihonorable.card-defense-factor-armor {
