body.rok-menu-mode .selected-unit-command-panel,
body.rok-menu-mode .persistent-unit-command-stack {
  visibility: hidden !important;
  pointer-events: none !important;
}

body.rok-menu-mode .transition-overlay {
  display: none !important;
}

body.rok-battle-mode #mainMenuScreen {
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
}

.main-menu-screen {
  position: fixed;
  inset: 0;
  z-index: var(--rok-main-menu-z);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 0 clamp(16px, 3vw, 54px) var(--rok-main-menu-buttons-bottom);
  background-image: url('assets/menu/main-menu-bg.png');
  background-size: cover;
  background-position: center center;
  background-repeat: no-repeat;
  overflow: hidden;
  transition: opacity .28s ease, visibility .28s ease;
}

.main-menu-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 50% 42%, rgba(38, 26, 67, .04), rgba(0, 0, 0, .16) 52%, rgba(0, 0, 0, .48) 100%),
    linear-gradient(to top, rgba(0, 0, 0, .54), rgba(0, 0, 0, 0) 34%);
}

.main-menu-buttons {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: repeat(3, var(--rok-main-menu-btn-w));
  gap: var(--rok-main-menu-btn-gap-y) var(--rok-main-menu-btn-gap-x);
  justify-content: center;
  align-items: center;
  max-width: min(94vw, 1120px);
}

.main-menu-btn {
  position: relative;
  display: block;
  width: var(--rok-main-menu-btn-w);
  aspect-ratio: 3 / 1;
  padding: 0;
  border: 0;
  outline: 0;
  background: transparent;
  cursor: pointer;
  filter: drop-shadow(0 14px 22px rgba(0, 0, 0, .55));
  transform: translateZ(0) scale(1);
  transition: transform .16s ease, filter .16s ease, opacity .16s ease;
}

.main-menu-btn img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  pointer-events: none;
}

.main-menu-btn:hover,
.main-menu-btn:focus-visible {
  transform: translateY(-3px) scale(1.025);
  filter: drop-shadow(0 18px 28px rgba(0, 0, 0, .68)) drop-shadow(0 0 16px rgba(177, 95, 255, .28));
}

.main-menu-btn-play:hover,
.main-menu-btn-play:focus-visible {
  filter: drop-shadow(0 18px 30px rgba(0, 0, 0, .72)) drop-shadow(0 0 20px rgba(190, 78, 255, .42));
}

.main-menu-btn-disabled {
  opacity: .82;
}

.main-menu-btn-disabled:hover,
.main-menu-btn-disabled:focus-visible {
  opacity: 1;
}

.main-menu-notice {
  position: absolute;
  left: 50%;
  bottom: clamp(8px, 1.8vh, 18px);
  transform: translateX(-50%);
  z-index: 3;
  min-height: 22px;
  padding: 6px 16px;
  border-radius: 999px;
  border: 1px solid rgba(223, 197, 139, .28);
  background: rgba(5, 4, 12, .54);
  color: rgba(246, 229, 190, .92);
  font-family: Cinzel, Georgia, serif;
  font-size: clamp(11px, 1.15vw, 15px);
  letter-spacing: .08em;
  text-transform: uppercase;
  text-shadow: 0 2px 10px rgba(0, 0, 0, .9);
  opacity: .92;
}

.main-menu-notice:empty {
  opacity: 0;
}

.main-menu-notice.pulse {
  animation: mainMenuNoticePulse .6s ease both;
}

@keyframes mainMenuNoticePulse {
  0% { transform: translateX(-50%) scale(.96); opacity: .35; }
  55% { transform: translateX(-50%) scale(1.035); opacity: 1; }
  100% { transform: translateX(-50%) scale(1); opacity: .92; }
}

