body.rok-library-mode .game-shell,
body.rok-library-mode .selected-unit-command-panel,
body.rok-library-mode .persistent-unit-command-stack,
body.rok-library-mode #mainMenuScreen {
  visibility: hidden !important;
  pointer-events: none !important;
}

body.rok-library-mode .transition-overlay {
  display: none !important;
}

.library-builder-screen {
  position: fixed;
  inset: 0;
  z-index: var(--library-builder-z);
  display: none;
  overflow: hidden;
  color: #f6edf9;
  background: #05050b;
}

body.rok-library-mode .library-builder-screen,
.library-builder-screen[aria-hidden="false"] {
  display: block;
}

.library-builder-bg {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(4, 5, 12, .76), rgba(9, 6, 16, .52) 46%, rgba(5, 3, 10, .82)),
    radial-gradient(circle at 50% 24%, rgba(142, 82, 255, .18), transparent 40%),
    url('assets/menu/main-menu-bg.png') center center / cover no-repeat;
  filter: saturate(.9) brightness(.72);
  transform: scale(1.012);
}

.library-builder-shell {
  position: relative;
  z-index: 2;
  height: 100%;
  display: grid;
  grid-template-rows: var(--library-builder-hud-h) minmax(0, 1fr);
  gap: var(--library-builder-gap);
  padding: clamp(12px, 1.6vw, 24px);
  box-sizing: border-box;
}

.library-builder-hud {
  display: grid;
  grid-template-columns: minmax(320px, 1fr) minmax(320px, .95fr);
  gap: var(--library-builder-gap);
  min-height: 0;
}

.library-builder-hud-block,
.library-builder-panel,
.library-builder-actions {
  border: 1px solid rgba(221, 196, 136, .28);
  background:
    linear-gradient(180deg, rgba(18, 14, 28, .84), rgba(6, 5, 12, .78));
  box-shadow:
    0 14px 34px rgba(0,0,0,.42),
    inset 0 0 22px rgba(255,255,255,.045),
    inset 0 0 0 1px rgba(255,255,255,.035);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.library-builder-hud-block {
  border-radius: 16px;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: hidden;
}

.library-builder-summary-hud {
  text-align: right;
}

.library-builder-kicker,
.library-builder-panel-head span {
  display: block;
  color: #caa8ff;
  font: 700 11px/1.2 system-ui, sans-serif;
  letter-spacing: .16em;
  text-transform: uppercase;
}

.library-builder-hud-block strong,
.library-builder-panel-head strong {
  display: block;
  color: #ffeec2;
  font: 800 clamp(17px, 1.45vw, 24px)/1.1 Georgia, serif;
  text-shadow: 0 2px 12px rgba(0,0,0,.75);
}

.library-builder-hud-block small {
  color: rgba(244, 235, 255, .72);
  font: 600 clamp(11px, .9vw, 14px)/1.25 system-ui, sans-serif;
  margin-top: 5px;
}

.library-builder-layout {
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(360px, 1.05fr) var(--library-builder-actions-w) minmax(360px, 1fr);
  gap: var(--library-builder-gap);
}

.library-builder-panel {
  min-height: 0;
  border-radius: var(--library-builder-panel-radius);
  padding: 12px;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  overflow: hidden;
}

.library-builder-library-panel {
  border-color: rgba(0, 245, 255, .24);
  background:
    linear-gradient(180deg, rgba(6, 30, 45, .82), rgba(5, 7, 16, .82));
  grid-template-rows: auto auto minmax(0, 1fr);
}

.library-builder-spellbook-panel {
  border-color: rgba(255, 184, 92, .24);
  background:
    linear-gradient(180deg, rgba(55, 12, 10, .70), rgba(12, 5, 8, .84));
}

.library-builder-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 0 2px 10px;
}

.library-builder-page-chip {
  border: 1px solid rgba(255,255,255,.16);
  border-radius: 999px;
  padding: 6px 10px;
  background: rgba(0,0,0,.36);
  color: #f6edf9;
  font: 800 12px/1 system-ui, sans-serif;
}

.library-builder-card-grid {
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  display: grid;
  gap: 8px;
  padding: 4px 4px 10px;
  scrollbar-width: thin;
  scrollbar-color: rgba(217, 193, 255, .45) rgba(0,0,0,.22);
}

.library-builder-library-grid {
  grid-template-columns: repeat(auto-fill, minmax(92px, 1fr));
  align-content: start;
  row-gap: var(--biblioteca-cartas-separacion-vertical) !important;
  column-gap: var(--biblioteca-cartas-separacion-horizontal) !important;
  gap: var(--biblioteca-cartas-separacion-vertical) var(--biblioteca-cartas-separacion-horizontal) !important;
}

.library-builder-spellbook-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-template-rows: repeat(4, auto);
  align-content: start;
  overflow: hidden;
}

.library-builder-card-tile {
  position: relative;
  display: block;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  aspect-ratio: var(--card-skin-aspect);
  padding: 0;
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(10,10,16,.82), rgba(2,2,5,.92));
  box-shadow: inset 0 0 18px rgba(0,0,0,.72), 0 6px 16px rgba(0,0,0,.34);
  cursor: pointer;
  overflow: hidden;
  transition: transform .14s ease, border-color .14s ease, box-shadow .14s ease;
}

.library-builder-card-tile:hover,
.library-builder-card-tile:focus-visible {
  transform: translateY(-2px);
  border-color: rgba(255,238,194,.58);
  box-shadow: inset 0 0 18px rgba(0,0,0,.62), 0 8px 18px rgba(0,0,0,.45), 0 0 14px rgba(194, 116, 255, .22);
}

.library-builder-card-tile.selected {
  border-color: #fff2b2;
  box-shadow: inset 0 0 18px rgba(0,0,0,.52), 0 0 0 2px rgba(255, 224, 116, .28), 0 0 22px rgba(255, 206, 98, .25);
}

.library-builder-card-tile.empty {
  cursor: default;
  border-style: dashed;
  border-color: rgba(255,255,255,.12);
  background: linear-gradient(180deg, rgba(255,255,255,.035), rgba(0,0,0,.22));
}

.library-builder-empty-mark {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: rgba(255,255,255,.09);
  font-size: 34px;
}

.library-builder-card-tile .card {
  position: absolute !important;
  left: 6px !important;
  right: 6px !important;
  top: 6px !important;
  bottom: 6px !important;
  inset: 6px !important;
  aspect-ratio: var(--card-skin-aspect) !important;
  border-radius: 6px;
}

.library-builder-card-tile .card-layer {
  pointer-events: none !important;
}

.library-builder-actions {
  border-radius: 16px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 0;
  overflow: auto;
}

.library-builder-action,
.library-builder-mini-btn {
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 12px;
  background: linear-gradient(180deg, rgba(35, 27, 51, .95), rgba(9, 8, 15, .94));
  color: #f9f0ff;
  font: 900 12px/1.15 system-ui, sans-serif;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 10px 10px;
  cursor: pointer;
  box-shadow: inset 0 0 12px rgba(255,255,255,.045), 0 5px 12px rgba(0,0,0,.28);
}

.library-builder-action:hover,
.library-builder-mini-btn:hover,
.library-builder-action:focus-visible,
.library-builder-mini-btn:focus-visible {
  border-color: rgba(255, 229, 154, .55);
  transform: translateY(-1px);
}

.library-builder-action.primary {
  background: linear-gradient(180deg, rgba(82, 43, 139, .98), rgba(22, 11, 42, .98));
  border-color: rgba(204, 152, 255, .48);
}

.library-builder-action.danger {
  background: linear-gradient(180deg, rgba(97, 27, 31, .96), rgba(25, 8, 12, .98));
  border-color: rgba(255, 132, 132, .38);
}

.library-builder-action.back {
  margin-top: auto;
  background: linear-gradient(180deg, rgba(25, 41, 56, .96), rgba(8, 12, 18, .98));
}

.library-builder-action.planned,
.library-builder-mini-btn.planned {
  opacity: .72;
}

.library-builder-notice {
  min-height: 44px;
  padding: 8px;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,.1);
  background: rgba(0,0,0,.24);
  color: rgba(245, 237, 255, .85);
  font: 700 11px/1.25 system-ui, sans-serif;
}

.library-builder-notice:empty::before {
  content: 'Selecciona cartas para construir el Spellbook.';
  color: rgba(245, 237, 255, .46);
}

.library-builder-notice.pulse {
  animation: libraryBuilderNoticePulse .55s ease both;
}

@keyframes libraryBuilderNoticePulse {
  0% { opacity: .42; transform: scale(.985); }
  55% { opacity: 1; transform: scale(1.015); }
  100% { opacity: 1; transform: scale(1); }
}

.library-builder-page-row {
  display: flex;
  gap: 8px;
  justify-content: space-between;
  padding: 8px 2px 0;
}

.library-builder-page-row .library-builder-mini-btn {
  flex: 1;
  padding: 8px;
  font-size: 11px;
}

@media (max-width: 1050px) {
  :root {
    --library-builder-hud-h: 118px;
    --library-builder-actions-w: 145px;
  }
  .library-builder-layout {
    grid-template-columns: minmax(260px, 1fr) var(--library-builder-actions-w) minmax(260px, 1fr);
  }
  .library-builder-library-grid {
    grid-template-columns: repeat(auto-fill, minmax(78px, 1fr));
  }
}


/* =========================================================
