  grid-template-rows: repeat(4, var(--library-builder-spellbook-slot-size)) !important;
  grid-auto-rows: var(--library-builder-spellbook-slot-size) !important;
  justify-content: center !important;
  align-content: start !important;
  justify-items: stretch !important;
