  min-height: 0 !important;
  max-width: var(--library-builder-spellbook-slot-size) !important;
  max-height: var(--library-builder-spellbook-slot-size) !important;
  aspect-ratio: 1 / 1 !important;
}

/* En pantallas más bajas, baja otro poco para que no se coma los botones de página. */
