/* =========================================================
   ROK v5.5.78 · COLEGAS DE GUERRA LISTO EN SPELLBOOK
   =========================================================
   Toyotomi Hideyoshi brilla cuando Oda Nobunaga está en arena
   y su casteo instantáneo condicionado está disponible.
*/

.card .war-colleagues-ready,
.war-colleagues-ready {
  position: relative !important;
  overflow: hidden !important;
  box-shadow:
    0 0 0 2px rgba(255, 218, 116, .76),
    0 0 16px rgba(255, 197, 66, .62),
    0 0 30px rgba(255, 244, 172, .32) !important;
  animation: warColleaguesPulse 1.55s ease-in-out infinite !important;
}

.war-colleagues-ready::after {
  content: "";
  position: absolute;
  inset: -28%;
  z-index: 9;
  pointer-events: none;
  background: linear-gradient(
    115deg,
    transparent 0%,
    transparent 36%,
    rgba(255, 255, 255, .16) 43%,
    rgba(255, 238, 158, .46) 49%,
    rgba(255, 255, 255, .18) 55%,
    transparent 64%,
    transparent 100%
  );
  transform: translateX(-78%) rotate(4deg);
  animation: warColleaguesFoilSweep 2.1s ease-in-out infinite;
  mix-blend-mode: screen;
}

@keyframes warColleaguesPulse {
  0%, 100% {
    filter: brightness(1);
  }
  50% {
    filter: brightness(1.18) saturate(1.12);
  }
}

@keyframes warColleaguesFoilSweep {
  0% {
    transform: translateX(-82%) rotate(4deg);
    opacity: 0;
  }
  18% {
    opacity: .75;
  }
  58% {
    opacity: .95;
  }
  100% {
    transform: translateX(82%) rotate(4deg);
    opacity: 0;
  }
}


