  to { filter: brightness(1.16) saturate(1.18); }
}


/* =========================================================
   ROK v53 · AJUSTE TEMPORAL HUD RIVAL DE KASTEO
   Solo esta sección usa los controles activos v53 de arriba.
   ========================================================= */
.enemy-mini-hud {
  width: var(--v53-enemy-hud-w) !important;
  height: var(--v53-enemy-hud-h) !important;
  transform: translate(var(--v53-enemy-hud-x), var(--v53-enemy-hud-y)) scale(var(--v53-enemy-hud-scale)) !important;
  transform-origin: left top !important;
  overflow: visible !important;
  pointer-events: auto !important;
}

.enemy-mini-cast-queue {
  position: relative !important;
  display: flex !important;
  flex-direction: row !important;
  flex-wrap: nowrap !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: var(--v53-enemy-cast-gap) !important;
  width: var(--v53-enemy-cast-area-w) !important;
  height: var(--v53-enemy-cast-area-h) !important;
  min-height: var(--v53-enemy-cast-area-h) !important;
  max-height: var(--v53-enemy-cast-area-h) !important;
  padding: 0 calc(var(--v53-enemy-more-size) + 6px) 0 0 !important;
  margin: var(--v53-enemy-cast-area-y) 0 0 var(--v53-enemy-cast-area-x) !important;
  overflow-x: auto !important;
  overflow-y: visible !important;
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
  pointer-events: auto !important;
