/* =========================================================
   ROK v91 · QUEMADURA VISUAL · TICK EN PERSISTENTES + VS
   - Cuando Quemadura hace daño, vibra/brilla solo:
     1) miniatura persistente inferior
     2) tarjeta VS/combat HUD
   - La miniatura seleccionada no recibe este pulso.
   ========================================================= */
.persistent-unit-command-item.progressive-factor-card-pulse-burn,
.combat-side.progressive-factor-card-pulse-burn {
  animation: burnSustainMiniTickPulse .78s cubic-bezier(.18,.78,.22,1) both !important;
  will-change: transform, filter;
}

.persistent-unit-command-item.progressive-factor-card-pulse-burn .selected-unit-command-card,
.combat-side.progressive-factor-card-pulse-burn .combat-mini-card {
  animation: burnSustainCardGlow .78s cubic-bezier(.18,.78,.22,1) both !important;
}

@keyframes burnSustainMiniTickPulse {
  0%   { transform: translateX(0) scale(1); filter: brightness(1); }
  12%  { transform: translateX(-2px) scale(1.015); filter: brightness(1.18) saturate(1.12); }
  24%  { transform: translateX(2px) scale(1.018); filter: brightness(1.24) saturate(1.18); }
  38%  { transform: translateX(-3px) scale(1.02); filter: brightness(1.32) saturate(1.22); }
  52%  { transform: translateX(3px) scale(1.018); filter: brightness(1.22) saturate(1.16); }
  70%  { transform: translateX(-1px) scale(1.01); filter: brightness(1.12) saturate(1.08); }
  100% { transform: translateX(0) scale(1); filter: brightness(1); }
}

@keyframes burnSustainCardGlow {
  0% {
    box-shadow: 0 0 0 rgba(255, 105, 24, 0), 0 10px 18px rgba(0,0,0,.38);
    filter: brightness(1) saturate(1);
  }
  18% {
    box-shadow:
      0 0 0 2px rgba(255, 173, 70, .75),
      0 0 16px rgba(255, 91, 22, .62),
      0 0 28px rgba(255, 38, 0, .30),
      0 10px 18px rgba(0,0,0,.42) !important;
    filter: brightness(1.28) saturate(1.24);
  }
  50% {
    box-shadow:
      0 0 0 1px rgba(255, 173, 70, .55),
      0 0 12px rgba(255, 91, 22, .45),
      0 0 22px rgba(255, 38, 0, .24),
      0 10px 18px rgba(0,0,0,.42) !important;
    filter: brightness(1.18) saturate(1.16);
  }
  100% {
    box-shadow: 0 0 0 rgba(255, 105, 24, 0), 0 10px 18px rgba(0,0,0,.38);
    filter: brightness(1) saturate(1);
  }
}

