@keyframes nobunagaTokenBonusImpact {
  0% { transform: translateY(0) scale(1); filter: brightness(1) saturate(1); }
  24% { transform: translateY(-5px) scale(1.045); filter: brightness(1.14) saturate(1.18) drop-shadow(0 0 8px rgba(255, 140, 36, .28)); }
  52% { transform: translateY(1px) scale(1.012); filter: brightness(1.24) saturate(1.28) drop-shadow(0 0 12px rgba(255, 98, 24, .36)); }
  76% { transform: translateY(-1px) scale(1.018); filter: brightness(1.10) saturate(1.12) drop-shadow(0 0 7px rgba(255, 152, 52, .24)); }
  100% { transform: translateY(0) scale(1); filter: brightness(1) saturate(1); }
}
@keyframes nobunagaGroundPulse {
  0% { opacity: 0; transform: translate(-50%, -18%) scale(.78); }
  42% { opacity: 0; transform: translate(-50%, -10%) scale(.82); }
  56% { opacity: .52; transform: translate(-50%, 0%) scale(1.02); }
  100% { opacity: 0; transform: translate(-50%, 10%) scale(1.28); }
}
@keyframes nobunagaBuffTextFloat {
  0% { opacity: 0; transform: translateY(8px) scale(.72); filter: blur(.5px); }
  12% { opacity: 1; transform: translateY(-2px) scale(1.08); filter: blur(0); }
  62% { opacity: 1; transform: translateY(-14px) scale(1); filter: blur(0); }
  100% { opacity: 0; transform: translateY(-34px) scale(.94); filter: blur(.8px); }
}

