/* =========================================================
   ROK v181 · Foil visible sobre la imagen real del Kaster
   El brillo ya no depende de un rectángulo externo ni de mask-url:
   se aplica sobre una copia del token y queda recortado por el alpha
   propio de la imagen.
   ========================================================= */
.unit.offturn-caster-foil {
  z-index: 760 !important;
  overflow: visible !important;
}
.unit.offturn-caster-foil > .unit-token-img {
  filter:
    drop-shadow(1px 0 0 rgba(255,255,255,.96))
    drop-shadow(-1px 0 0 rgba(255,255,255,.96))
    drop-shadow(0 1px 0 rgba(255,255,255,.96))
    drop-shadow(0 -1px 0 rgba(255,255,255,.96))
    drop-shadow(0 0 10px rgba(255,255,255,.70))
    drop-shadow(0 0 18px var(--unit-glow, #ffffff))
    saturate(1.12) brightness(1.07) !important;
}
.offturn-caster-token-foil-img {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: contain !important;
  pointer-events: none !important;
  z-index: 9 !important;
  opacity: .96 !important;
  filter:
    brightness(2.25)
    contrast(1.18)
    saturate(1.45)
    drop-shadow(0 0 9px rgba(255,255,255,.74)) !important;
  mix-blend-mode: screen !important;
  -webkit-mask-image: linear-gradient(115deg, rgba(0,0,0,0) 0%, rgba(0,0,0,0) 31%, rgba(0,0,0,.92) 43%, rgba(0,0,0,1) 50%, rgba(0,0,0,.86) 57%, rgba(0,0,0,0) 70%, rgba(0,0,0,0) 100%);
