  -webkit-mask-size: 260% 100%;
  mask-size: 260% 100%;
  -webkit-mask-position: 120% 50%;
  mask-position: 120% 50%;
  animation: offturn-caster-token-foil-sweep 1.05s ease-in-out infinite;
}
.unit.offturn-caster-foil::after {
  content: none !important;
}
@keyframes offturn-caster-token-foil-sweep {
  0% {
    -webkit-mask-position: 120% 50%;
    mask-position: 120% 50%;
    opacity: .28;
  }
  18% { opacity: .72; }
  48% { opacity: 1; }
  82% { opacity: .72; }
  100% {
    -webkit-mask-position: -45% 50%;
    mask-position: -45% 50%;
    opacity: .28;
  }
}
