/* =========================================================
   ROK v5.5.105 · Contador anclado al panel real
   ========================================================= */

/* En la acción del Kaster existe un único contador: el integrado en la
   miniatura. La burbuja externa del dock queda anulada solo para este flujo. */
.quick-reaction-command-dock--caster > .quick-reaction-command-dock-timer {
  display: none !important;
}

/* El contador se inserta como hijo directo del panel real, por lo que
   se posiciona respecto a la miniatura completa y no al host de estados. */
.selected-unit-command-panel--offturn-caster .selected-unit-command-countdown {
  /* Dentro del skin, no fuera del panel: evita que el overflow del dock lo
     recorte o lo deje fuera de la pantalla. */
  top: 5px !important;
  left: 5px !important;
  right: auto !important;
  bottom: auto !important;
  z-index: 80 !important;
  visibility: visible !important;
  opacity: 1 !important;
}

.quick-reaction-command-dock--caster .selected-unit-command-countdown {
  display: inline-flex !important;
}

/* Kaster kasteando una invocación de 1+ fases: círculo persistente centrado. */
.caster-persistent-cast-circle {
  position: absolute;
  left: 50%;
  top: 52%;
  width: 32.4%;
  height: auto;
  aspect-ratio: 1 / 1;
  transform: translate(-50%, -50%);
  z-index: 18;
  pointer-events: none;
  display: grid;
  place-items: center;
  mix-blend-mode: screen;
  filter:
    drop-shadow(0 0 4px rgba(255,255,255,.88))
    drop-shadow(0 0 12px var(--caster-cast-color, #ffffff));
}
.caster-persistent-cast-circle::before {
  content: '';
  position: absolute;
  inset: 18%;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--caster-cast-color, #fff) 42%, white 58%) 0%, color-mix(in srgb, var(--caster-cast-color, #fff) 26%, transparent 74%) 42%, transparent 74%);
  opacity: .30;
  filter: blur(5px);
  animation: casterPersistentCastGlow 1.8s ease-in-out infinite alternate;
  animation-delay: var(--caster-cast-glow-delay, 0ms);
}
.caster-persistent-cast-circle img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  opacity: .88;
  animation: casterPersistentCastSpin 4.2s linear infinite;
  animation-delay: var(--caster-cast-spin-delay, 0ms);
  filter:
    drop-shadow(0 0 4px rgba(255,255,255,.92))
    drop-shadow(0 0 11px var(--caster-cast-color, #ffffff));
}
@keyframes casterPersistentCastSpin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
@keyframes casterPersistentCastGlow {
  from { opacity: .18; transform: scale(.90); }
  to { opacity: .38; transform: scale(1.08); }
}

/* =========================================================
   ROK v201 / v5.5.115 · GUARDIANES Y KASTEO PERSISTENTE
   Aura circular radio 3, canalización y recompensa elemental.
   ========================================================= */
.guardian-aura-layer,
.guardian-channel-fx-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: visible;
}

.guardian-aura-layer {
  z-index: 4;
}

.guardian-channel-fx-layer {
  z-index: 35;
}

.guardian-aura-field {
  position: absolute;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 2px solid var(--guardian-aura-color, #9b4dff);
  background: rgba(var(--guardian-aura-rgb, 155, 77, 255), .25);
  box-shadow:
    inset 0 0 22px rgba(var(--guardian-aura-rgb, 155, 77, 255), .18),
    0 0 12px rgba(var(--guardian-aura-rgb, 155, 77, 255), .66),
    0 0 26px rgba(var(--guardian-aura-rgb, 155, 77, 255), .28);
  opacity: .25;
  transition: opacity .24s ease, filter .24s ease;
  animation: guardianAuraBreath 2.8s ease-in-out infinite alternate;
}

.guardian-aura-field.guardian-aura-field--active {
  opacity: .50;
}

.guardian-aura-field::after {
  content: '';
  position: absolute;
  inset: -4px;
  border-radius: inherit;
  border: 1px solid rgba(255,255,255,.42);
  opacity: .62;
}

@keyframes guardianAuraBreath {
  from {
    filter: brightness(.92) saturate(1.02);
    box-shadow:
      inset 0 0 18px rgba(var(--guardian-aura-rgb, 155, 77, 255), .14),
      0 0 10px rgba(var(--guardian-aura-rgb, 155, 77, 255), .56),
      0 0 22px rgba(var(--guardian-aura-rgb, 155, 77, 255), .22);
  }
  to {
    filter: brightness(1.12) saturate(1.18);
    box-shadow:
      inset 0 0 28px rgba(var(--guardian-aura-rgb, 155, 77, 255), .24),
      0 0 16px rgba(var(--guardian-aura-rgb, 155, 77, 255), .78),
      0 0 34px rgba(var(--guardian-aura-rgb, 155, 77, 255), .34);
  }
}

.guardian-channel-beam {
  position: absolute;
  height: 10px;
  transform-origin: 0 50%;
  opacity: .74;
  filter:
    drop-shadow(0 0 5px var(--guardian-channel-color, #9b4dff))
    drop-shadow(0 0 12px rgba(var(--guardian-channel-rgb, 155, 77, 255), .62));
  transition: width .18s linear, left .18s linear, top .18s linear, transform .18s linear;
}

.guardian-channel-beam-core {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 3px;
  transform: translateY(-50%);
  border-radius: 999px;
  background: linear-gradient(90deg,
    rgba(255,255,255,.94) 0%,
    var(--guardian-channel-color, #9b4dff) 20%,
    rgba(var(--guardian-channel-rgb, 155, 77, 255), .32) 74%,
    rgba(255,255,255,.84) 100%);
  box-shadow:
    0 0 7px var(--guardian-channel-color, #9b4dff),
    0 0 14px rgba(var(--guardian-channel-rgb, 155, 77, 255), .64);
  overflow: hidden;
}

.guardian-channel-beam-core::after {
  content: '';
  position: absolute;
  top: -2px;
  bottom: -2px;
  width: 34%;
  left: -36%;
  border-radius: inherit;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.98), transparent);
  animation: guardianChannelFlow 1.05s linear infinite;
}

.guardian-channel-origin,
.guardian-channel-target {
  position: absolute;
  top: 50%;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle, #fff 0 18%, var(--guardian-channel-color, #9b4dff) 34% 62%, transparent 72%);
  box-shadow: 0 0 12px var(--guardian-channel-color, #9b4dff);
}

