/* =========================================================
   ROK v398 · SELECTOR DE MODO VS BOT
   ========================================================= */
.bot-match-mode-modal {
  position: fixed;
  inset: 0;
  z-index: 72100;
  display: none;
  place-items: center;
  padding: 24px;
  background: rgba(0, 0, 0, .78);
  backdrop-filter: blur(6px);
}
.bot-match-mode-modal.open { display: grid; }
.bot-match-mode-card {
  position: relative;
  width: min(720px, 94vw);
  display: grid;
  gap: 13px;
  padding: 26px;
  border: 1px solid rgba(204, 160, 255, .58);
  background: radial-gradient(circle at 20% 0%, rgba(135, 68, 205, .22), transparent 36%), linear-gradient(180deg, rgba(19, 15, 27, .99), rgba(5, 5, 9, .99));
  box-shadow: 0 0 44px rgba(117, 53, 192, .3), inset 0 0 34px rgba(0, 0, 0, .72);
}
.bot-match-mode-close {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 30px;
  height: 30px;
  border: 1px solid rgba(255,255,255,.28);
  background: rgba(0,0,0,.48);
  color: #fff;
  font: 22px/1 Arial, sans-serif;
  cursor: pointer;
}
.bot-match-mode-kicker { color: #b994e6; font: 900 11px/1 Arial, sans-serif; letter-spacing: .18em; }
.bot-match-mode-card h2 { margin: 0; color: #f0e5ff; font: 900 31px/1.05 Georgia, serif; }
.bot-match-mode-card > p { margin: 0; color: #bdb2c8; font: 13px/1.45 Arial, sans-serif; }
.bot-match-mode-options { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 4px; }
.bot-match-mode-option {
  min-height: 132px;
  display: grid;
  align-content: center;
  gap: 10px;
  padding: 20px;
  border: 1px solid rgba(255,255,255,.16);
  background: linear-gradient(145deg, rgba(29, 22, 42, .96), rgba(8, 7, 13, .98));
  color: #fff;
  text-align: left;
  cursor: pointer;
  transition: transform .16s ease, border-color .16s ease, box-shadow .16s ease;
}
.bot-match-mode-option:hover,
.bot-match-mode-option:focus-visible { transform: translateY(-2px); border-color: rgba(203,159,255,.76); box-shadow: 0 0 20px rgba(155,77,255,.26); }
.bot-match-mode-option-test { border-color: rgba(255,190,80,.34); background: radial-gradient(circle at 85% 15%, rgba(255,169,55,.14), transparent 35%), linear-gradient(145deg, rgba(37, 26, 31, .96), rgba(9, 7, 11, .98)); }
.bot-match-mode-option strong { color: #f7edff; font: 900 22px/1 Georgia, serif; }
.bot-match-mode-option span { color: #bdb3c7; font: 12px/1.45 Arial, sans-serif; }
@media (max-width: 650px) { .bot-match-mode-options { grid-template-columns: 1fr; } }

/* =========================================================
   ROK v245 · SELECTOR DE SPELLBOOK ANTES DE PARTIDA
   ========================================================= */
.match-spellbook-select-modal {
  position: fixed;
  inset: 0;
  z-index: 72000;
  display: none;
  place-items: center;
  padding: 24px;
  background: rgba(0, 0, 0, .76);
  backdrop-filter: blur(5px);
}
.match-spellbook-select-modal.open {
  display: grid;
}
.match-spellbook-select-card {
  position: relative;
  width: min(880px, 94vw);
  max-height: 88vh;
  display: grid;
  grid-template-rows: auto auto auto minmax(170px, 1fr) auto auto;
  gap: 10px;
  overflow: hidden;
  padding: 24px;
  border: 1px solid rgba(177, 112, 255, .55);
  background:
    radial-gradient(circle at 15% 0%, rgba(136, 66, 211, .20), transparent 34%),
    linear-gradient(180deg, rgba(19, 15, 27, .985), rgba(5, 5, 9, .99));
  box-shadow: 0 0 42px rgba(117, 53, 192, .28), inset 0 0 35px rgba(0, 0, 0, .74);
}
.match-spellbook-select-close {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 30px;
  height: 30px;
  border: 1px solid rgba(255,255,255,.28);
  background: rgba(0,0,0,.48);
  color: #fff;
  font: 22px/1 Arial, sans-serif;
  cursor: pointer;
}
.match-spellbook-select-kicker {
  color: #b994e6;
  font: 900 11px/1 Arial, sans-serif;
  letter-spacing: .18em;
}
.match-spellbook-select-card h2 {
  margin: 0;
  color: #f0e5ff;
  font: 900 32px/1 Georgia, serif;
  letter-spacing: .03em;
}
.match-spellbook-select-card > p {
  margin: 0;
  color: #bdb2c8;
  font: 13px/1.4 Arial, sans-serif;
}
.match-spellbook-select-list {
  min-height: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 5px 5px 5px 0;
  scrollbar-width: none;
}
.match-spellbook-select-list::-webkit-scrollbar { width: 0; height: 0; }
.match-spellbook-option {
  min-height: 126px;
  display: grid;
  grid-template-columns: 104px minmax(0, 1fr);
  gap: 13px;
  align-items: center;
  padding: 10px;
  border: 1px solid rgba(255,255,255,.13);
  background: linear-gradient(145deg, rgba(29, 22, 42, .94), rgba(8, 7, 13, .97));
  color: #fff;
  text-align: left;
  cursor: pointer;
  transition: border-color .16s ease, box-shadow .16s ease, transform .16s ease;
}
.match-spellbook-option:not(:disabled):hover {
  border-color: rgba(203, 159, 255, .70);
  box-shadow: 0 0 18px rgba(155, 77, 255, .22);
  transform: translateY(-1px);
}
.match-spellbook-option.selected {
  border-color: #c58cff;
  box-shadow: 0 0 0 2px rgba(155,77,255,.30), 0 0 22px rgba(155,77,255,.32);
}
.match-spellbook-option.unavailable {
  opacity: .46;
  cursor: not-allowed;
  filter: grayscale(.45);
}
.match-spellbook-option-visual {
  position: relative;
  display: block;
  width: 98px;
  height: 98px;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.18);
  background: #08070c;
}
.match-spellbook-option-card {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
}
.match-spellbook-option-card .key-label { display: none !important; }
.match-spellbook-option-info {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.match-spellbook-option-info > strong {
  overflow: hidden;
  color: #f5ebff;
  font: 900 20px/1.05 Georgia, serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.match-spellbook-option-info > small {
  color: #bca9d3;
  font: 800 11px/1 Arial, sans-serif;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.match-spellbook-option-stats {
  color: #d3cbdc;
  font: 12px/1 Arial, sans-serif;
}
.match-spellbook-option-stats b { color: #fff; font-size: 15px; }
.match-spellbook-option-stats i { padding: 0 5px; color: #786a88; font-style: normal; }
.match-spellbook-option-elements {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.match-spellbook-option-elements > span {
  min-width: 46px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 2px 7px;
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 999px;
  background: rgba(0,0,0,.34);
}
.match-spellbook-option-elements img {
  width: 19px;
  height: 19px;
  object-fit: contain;
}
.match-spellbook-option-elements b { font: 900 12px/1 Arial, sans-serif; }
.match-spellbook-option-info em {
  color: #ffaaaa;
  font: 10px/1.25 Arial, sans-serif;
}
.match-spellbook-select-empty {
  min-height: 150px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 7px;
  border: 1px dashed rgba(255,255,255,.16);
  color: #d8cce2;
  text-align: center;
  font-family: Arial, sans-serif;
}
.match-spellbook-select-empty[hidden] { display: none !important; }
.match-spellbook-select-empty span { color: #94889f; font-size: 12px; }
.match-spellbook-select-notice {
  min-height: 19px;
  color: #bcaec8;
  font: 12px/1.4 Arial, sans-serif;
}
.match-spellbook-select-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}
.match-spellbook-select-actions button {
  min-width: 180px;
  height: 42px;
}
.match-spellbook-select-actions button:disabled {
  opacity: .38;
  cursor: not-allowed;
}
@media (max-width: 720px) {
  .match-spellbook-select-list { grid-template-columns: 1fr; }
  .match-spellbook-option { grid-template-columns: 82px minmax(0, 1fr); }
  .match-spellbook-option-visual { width: 78px; height: 78px; }
  .match-spellbook-select-actions { flex-direction: column-reverse; }
  .match-spellbook-select-actions button { width: 100%; }
}

