/* v251 · Gioshonin Camuflaje FX */
.floating-combat.floating-camuflaje {
  color: #f2ddff !important;
  text-shadow:
    0 0 6px rgba(242,221,255,.95),
    0 0 16px rgba(167,74,255,.95),
    0 0 28px rgba(111,31,182,.78) !important;
  letter-spacing: .08em;
}

.unit.unit-camuflaje-hidden {
  opacity: var(--camuflaje-opacity, .5);
}
.unit.unit-camuflaje-hidden .unit-token-img {
  filter: saturate(.85) hue-rotate(8deg) drop-shadow(0 0 10px rgba(165,85,255,.24));
}
.unit.unit-camuflaje-activating {
  animation: gioshoninCamuflajeHop 780ms cubic-bezier(.2,.9,.24,1) 1;
}
@keyframes gioshoninCamuflajeHop {
  0% { transform: translateY(0); }
  20% { transform: translateY(-10px) scale(1.02); }
  48% { transform: translateY(-5px) scale(1.01); }
  72% { transform: translateY(-8px) scale(1.015); }
  100% { transform: translateY(0) scale(1); }
}
.unit-camuflaje-fx {
  position: absolute;
  inset: -8px;
  pointer-events: none;
  z-index: 14;
}
.unit-camuflaje-ring,
.unit-camuflaje-mist {
  position: absolute;
  inset: 0;
  border-radius: 50%;
}
.unit-camuflaje-ring {
  border: 2px solid rgba(178,97,255,.8);
  box-shadow: 0 0 12px rgba(164,80,255,.45), inset 0 0 8px rgba(238,213,255,.22);
  opacity: 0;
}
.unit-camuflaje-ring-a {
  animation: gioshoninCamuflajeRingA 920ms ease-out 1;
}
.unit-camuflaje-ring-b {
  animation: gioshoninCamuflajeRingB 920ms ease-out 1;
}
.unit-camuflaje-mist {
  background:
    radial-gradient(circle at 30% 32%, rgba(235,206,255,.42), rgba(235,206,255,0) 34%),
    radial-gradient(circle at 68% 38%, rgba(165,85,255,.34), rgba(165,85,255,0) 38%),
    radial-gradient(circle at 42% 72%, rgba(111,31,182,.30), rgba(111,31,182,0) 44%);
  filter: blur(3px);
  animation: gioshoninCamuflajeMist 900ms ease-out 1;
}
@keyframes gioshoninCamuflajeRingA {
  0% { opacity: 0; transform: scale(.55); }
  18% { opacity: .95; }
  100% { opacity: 0; transform: scale(1.28); }
}
@keyframes gioshoninCamuflajeRingB {
  0%, 18% { opacity: 0; transform: scale(.78); }
  38% { opacity: .72; }
  100% { opacity: 0; transform: scale(1.52); }
}
@keyframes gioshoninCamuflajeMist {
  0% { opacity: 0; transform: scale(.72); }
  28% { opacity: .88; }
  100% { opacity: 0; transform: scale(1.24); }
}

/* =========================================================
   ROK v253 · MERCANCÍA DE GUERRA EN MODAL
   ========================================================= */
.gioshonin-supply-overlay {
  z-index: 12020;
}
.gioshonin-supply-modal-box {
  width: min(700px, calc(100vw - 28px));
  max-height: min(82vh, 760px);
  overflow: auto;
  border-color: rgba(190, 112, 255, .34);
  box-shadow:
    0 26px 90px rgba(0,0,0,.64),
    0 0 40px rgba(132, 44, 209, .18),
    inset 0 0 24px rgba(205, 149, 255, .045);
}
.gioshonin-supply-modal-body {
  margin-bottom: 14px;
}
.gioshonin-supply-target-grid {
  display: grid;
  gap: 10px;
  margin: 10px 0 18px;
}
.gioshonin-supply-unit-card,
.gioshonin-supply-selected-unit,
.gioshonin-supply-option-card {
  width: 100%;
  border-radius: 16px;
  border: 1px solid rgba(255,255,255,.13);
  background: linear-gradient(135deg, rgba(255,255,255,.07), rgba(122,45,185,.08));
  color: #fff;
}
.gioshonin-supply-unit-card {
  min-height: 88px;
  display: grid;
  grid-template-columns: 74px minmax(0,1fr) auto;
  align-items: center;
  gap: 13px;
  padding: 8px 12px 8px 8px;
  text-align: left;
  cursor: pointer;
  transition: transform .16s ease, border-color .16s ease, background .16s ease, box-shadow .16s ease;
}
.gioshonin-supply-unit-card:hover,
.gioshonin-supply-unit-card:focus-visible {
  transform: translateY(-2px);
  border-color: rgba(216,164,255,.66);
  background: linear-gradient(135deg, rgba(255,255,255,.1), rgba(148,57,220,.18));
  box-shadow: 0 8px 24px rgba(65,12,99,.28), inset 0 0 14px rgba(236,207,255,.06);
  outline: none;
}
.gioshonin-supply-unit-art {
  width: 68px;
  height: 68px;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: 14px;
  background: radial-gradient(circle, rgba(179,98,242,.2), rgba(10,8,13,.9));
  border: 1px solid rgba(255,255,255,.13);
}
.gioshonin-supply-unit-art img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter: drop-shadow(0 5px 7px rgba(0,0,0,.36));
}
.gioshonin-supply-unit-copy,
.gioshonin-supply-selected-unit > span:last-child {
  min-width: 0;
  display: grid;
  gap: 5px;
}
.gioshonin-supply-unit-copy strong,
.gioshonin-supply-selected-unit strong {
  font-size: 15px;
  line-height: 1.15;
}
.gioshonin-supply-unit-copy small,
.gioshonin-supply-selected-unit small {
  color: rgba(245,235,255,.7);
  line-height: 1.3;
}
.gioshonin-supply-unit-select {
  padding: 7px 11px;
  border-radius: 999px;
  background: rgba(163,73,230,.18);
  border: 1px solid rgba(213,158,255,.28);
  color: #efd9ff;
  font-size: 12px;
  font-weight: 800;
}
.gioshonin-supply-selected-unit {
  display: grid;
  grid-template-columns: 74px minmax(0,1fr);
  align-items: center;
  gap: 13px;
  padding: 9px;
}
.gioshonin-supply-option-card {
  display: grid;
  gap: 4px;
  padding: 13px 15px;
  text-align: left;
  cursor: pointer;
  transition: border-color .16s ease, background .16s ease, transform .16s ease;
}
.gioshonin-supply-option-card strong {
  font-size: 14px;
}
.gioshonin-supply-option-card span {
  color: rgba(239,218,255,.7);
  font-size: 12px;
}
.gioshonin-supply-option-card:hover:not(:disabled),
.gioshonin-supply-option-card:focus-visible:not(:disabled) {
  transform: translateY(-1px);
  border-color: rgba(216,164,255,.62);
  background: linear-gradient(135deg, rgba(255,255,255,.1), rgba(148,57,220,.18));
  outline: none;
}
.gioshonin-supply-option-card:disabled {
  opacity: .42;
  cursor: not-allowed;
}
.gioshonin-supply-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}
.gioshonin-supply-modal-actions .main-button {
  min-width: 120px;
}

/* El objetivo ya no usa un botón + sobre la ficha. */
.gioshonin-supply-target,
.gioshonin-supply-glyph,
.gioshonin-supply-menu-title {
  display: none !important;
}

/* Resultado visual del reabastecimiento. */
.floating-combat.floating-gioshonin-supply,
.floating-combat.floating-gioshonin-supply-target {
  color: #f6e7ff !important;
  text-shadow:
    0 0 7px rgba(255,255,255,.92),
    0 0 16px rgba(177,87,255,.88),
    0 0 30px rgba(99,28,153,.7) !important;
}
.unit.unit-gioshonin-supply-fx-active {
  animation: gioshoninSupplyPulse 720ms cubic-bezier(.18,.88,.22,1) 1;
}
.unit-gioshonin-supply-fx {
  position: absolute;
  inset: -10px;
  z-index: 18;
  pointer-events: none;
}
.unit-gioshonin-supply-ring,
.unit-gioshonin-supply-glow,
.unit-gioshonin-supply-spark {
  position: absolute;
  border-radius: 50%;
}
.unit-gioshonin-supply-ring {
  inset: 5%;
  border: 2px solid rgba(220,170,255,.84);
  box-shadow: 0 0 14px rgba(178,86,255,.66), inset 0 0 10px rgba(255,255,255,.2);
  animation: gioshoninSupplyRing 1050ms ease-out 1 forwards;
}
.unit-gioshonin-supply-glow {
  inset: 13%;
  background: radial-gradient(circle, rgba(245,225,255,.56), rgba(166,73,231,.24) 42%, rgba(78,13,113,0) 72%);
  filter: blur(2px);
  animation: gioshoninSupplyGlow 1000ms ease-out 1 forwards;
}
.unit-gioshonin-supply-spark {
  width: 6px;
  height: 6px;
  background: #f8eaff;
  box-shadow: 0 0 9px #c67aff, 0 0 16px rgba(167,76,235,.8);
}
.unit-gioshonin-supply-spark-a {
  left: 22%;
  top: 34%;
  animation: gioshoninSupplySparkA 900ms ease-out 1 forwards;
}
.unit-gioshonin-supply-spark-b {
  right: 20%;
  bottom: 30%;
  animation: gioshoninSupplySparkB 980ms ease-out 1 forwards;
}
@keyframes gioshoninSupplyPulse {
  0% { transform: translateY(0) scale(1); }
  28% { transform: translateY(-7px) scale(1.035); }
  58% { transform: translateY(-2px) scale(1.015); }
  100% { transform: translateY(0) scale(1); }
}
@keyframes gioshoninSupplyRing {
  0% { opacity: 0; transform: scale(.55); }
  22% { opacity: 1; }
  100% { opacity: 0; transform: scale(1.38); }
}
@keyframes gioshoninSupplyGlow {
  0% { opacity: 0; transform: scale(.68); }
  35% { opacity: .95; }
  100% { opacity: 0; transform: scale(1.2); }
}
@keyframes gioshoninSupplySparkA {
  0% { opacity: 0; transform: translate(0,8px) scale(.4); }
  30% { opacity: 1; }
  100% { opacity: 0; transform: translate(-16px,-24px) scale(1.2); }
}
@keyframes gioshoninSupplySparkB {
  0% { opacity: 0; transform: translate(0,4px) scale(.4); }
  34% { opacity: 1; }
  100% { opacity: 0; transform: translate(18px,-22px) scale(1.15); }
}
@media (max-width: 620px) {
  .gioshonin-supply-unit-card {
    grid-template-columns: 62px minmax(0,1fr);
  }
  .gioshonin-supply-unit-art {
    width: 56px;
    height: 56px;
  }
  .gioshonin-supply-unit-select {
    grid-column: 1 / -1;
    justify-self: stretch;
    text-align: center;
  }
  .gioshonin-supply-modal-actions {
    flex-direction: column-reverse;
  }
  .gioshonin-supply-modal-actions .main-button {
    width: 100%;
  }
}

/* v258 · aviso propio de Mercancía de guerra */
.gioshonin-supply-prompt {
  position: fixed;
  inset: 0;
  z-index: 10040;
  display: none;
  place-items: center;
  padding: 24px;
  background: rgba(5, 3, 10, .52);
  backdrop-filter: blur(3px);
