  grid-template-areas:
    "icon copy"
    "actions actions";
  gap: 16px 20px;
  align-items: center;
  padding: 22px;
  border: 1px solid rgba(194, 130, 255, .58);
  border-radius: 20px;
  background:
    radial-gradient(circle at 16% 22%, rgba(157, 72, 230, .28), transparent 34%),
