  top: -4% !important;
  transform: translate(-50%, -50%) scale(.75) !important;
  transform-origin: center center !important;
}

/* El foil duplicado de Yasugana debe copiar exactamente el tamaño y
   desplazamiento configurados para su token real. Aplica tanto al foil
   de movimiento pendiente como al foil de selección. */
