  transform-origin: center bottom !important;
  transform:
    translate(var(--yasugana-token-x), var(--yasugana-token-y))
    scale(var(--yasugana-token-size)) !important;
}

/* Toda la fila Elegir funciona como superficie de identificación. */
.target-access-row.target-access-row-hoverable {
  transition: background .15s ease, box-shadow .15s ease, transform .15s ease;
}
.target-access-row.target-access-row-hoverable:hover,
.target-access-row.target-access-row-hoverable:focus-within {
