.yasugana-projectile-crow.crow-1 { --crow-scale: .78; --yasugana-crow-image: url('assets/yasugana-crow-real-side.png'); animation: yasuganaProjectileCrowA 840ms ease-in-out 0ms 1; }
.yasugana-projectile-crow.crow-2 { --crow-scale: .96; --yasugana-crow-image: url('assets/yasugana-crow-real-front.png'); animation: yasuganaProjectileCrowB 840ms ease-in-out 0ms 1; }
.yasugana-projectile-crow.crow-3 { --crow-scale: .72; --yasugana-crow-image: url('assets/yasugana-crow-real-front-flip.png'); animation: yasuganaProjectileCrowC 840ms ease-in-out 0ms 1; }
