@keyframes yasuganaProjectileCrowA {
  0% { transform: translate(-20px, 6px) rotate(-18deg) scale(var(--crow-scale)) scaleY(.45); }
  30% { transform: translate(-8px, -4px) rotate(10deg) scale(var(--crow-scale)) scaleY(1); }
  60% { transform: translate(4px, -10px) rotate(-12deg) scale(var(--crow-scale)) scaleY(.45); }
