.minokage-targeting-end {
  opacity: .28 !important;
  box-shadow: 0 0 2px rgba(255,255,255,.18), 0 0 4px rgba(0,0,0,.46) !important;
}

/* Una fase antes: aparece el giro del ataque al 50% de tamaño/opacidad. */
.minokage-prelaunch-spin-fx {
  position: absolute;
  width: clamp(42px, 5.5%, 88px);
  aspect-ratio: 1;
  transform: translate(-50%, -50%) rotate(0deg) scale(.5);
  border-radius: 50%;
  pointer-events: none;
  opacity: 0;
  z-index: 13;
  background: conic-gradient(from 15deg,
    transparent 0 16%,
    rgba(255,255,255,.84) 19% 22%,
    rgba(0,0,0,.82) 25% 31%,
    transparent 35% 56%,
    rgba(255,255,255,.76) 61% 64%,
    rgba(0,0,0,.78) 67% 72%,
    transparent 76%);
  mask: radial-gradient(circle, transparent 0 45%, #000 51% 66%, transparent 72%);
  -webkit-mask: radial-gradient(circle, transparent 0 45%, #000 51% 66%, transparent 72%);
  filter: drop-shadow(0 0 4px rgba(255,255,255,.30));
  animation: minokage-prelaunch-spin .76s linear infinite;
  animation-play-state: paused;
}
.minokage-channel-persistent.minokage-channel-prelaunch .minokage-prelaunch-spin-fx {
  opacity: .50;
  animation-play-state: running;
}
@keyframes minokage-prelaunch-spin {
  from { transform: translate(-50%, -50%) rotate(0deg) scale(.5); }
  to { transform: translate(-50%, -50%) rotate(360deg) scale(.5); }
}

/* Durante la ejecución desaparecen ficha visual, arma/vida y demás badges.
