}

.carga-real-horse {
  position: absolute;
  display: block;
  transform: translate(-50%, -50%) scale(var(--horse-scale, 1));
  transform-origin: center;
  will-change: transform, opacity, left, top;
  animation: cargaRealHorsePulse .44s ease-in-out infinite alternate;
  animation-delay: calc(var(--horse-index, 0) * -55ms);
  filter:
    drop-shadow(0 0 3px rgba(255,249,231,.86))
    drop-shadow(0 0 calc(8px * var(--horse-glow, .8)) rgba(255,124,36,.76))
