  object-fit: contain;
  user-select: none;
  pointer-events: none;
  opacity: .97;
  filter:
    brightness(1.08)
    sepia(.72)
    saturate(2.35)
    hue-rotate(-12deg)
    drop-shadow(0 0 2px rgba(255,251,236,.95))
    drop-shadow(0 0 7px rgba(255,155,62,.8))
    drop-shadow(0 0 14px rgba(255,66,18,.56));
}

.carga-real-horse::after {
  content: '';
  position: absolute;
  inset: 10% 12% 8% 12%;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255,149,58,.26) 0%, rgba(255,58,18,.16) 45%, rgba(255,58,18,0) 76%);
