  transform: translate(-50%, -50%) rotate(180deg) scale(var(--horse-scale, 1));
}

.carga-real-direction-down .carga-real-horse {
  transform: translate(-50%, -50%) rotate(0deg) scale(var(--horse-scale, 1));
}

.carga-real-direction-up .carga-real-horse-img {
  transform: none;
}

.carga-real-direction-down .carga-real-horse-img {
  transform: none;
}

.carga-real-particle {
  position: absolute;
  width: calc(8px * var(--particle-scale, 1) * var(--particle-width-ratio, 1));
  height: calc(8px * var(--particle-scale, 1) * var(--particle-height-ratio, 1));
  border-radius: 999px;
  opacity: 0;
  transform: translate(-50%, -50%) rotate(var(--particle-rotation, 0deg));
  pointer-events: none;
  will-change: transform, opacity;
  animation: cargaRealParticleFloat var(--particle-duration, 1800ms) cubic-bezier(.16,.68,.34,1) forwards;
  animation-delay: var(--particle-delay, 0ms);
}

.carga-real-particle-dust {
  background: radial-gradient(circle, rgba(255,225,174,.55) 0%, rgba(188,109,62,.42) 42%, rgba(116,54,19,0) 76%);
