    0 0 12px rgba(255,184,112,.24),
    0 0 22px rgba(116,57,17,.22);
  filter: blur(1.2px);
}

.carga-real-particle-ember {
  width: calc(5px * var(--particle-scale, 1));
  height: calc(5px * var(--particle-scale, 1));
  background: radial-gradient(circle, rgba(255,255,232,.96) 0%, rgba(255,203,104,.92) 30%, rgba(255,92,16,.88) 68%, rgba(255,92,16,0) 100%);
  box-shadow:
    0 0 8px rgba(255,214,118,.62),
    0 0 18px rgba(255,78,22,.48);
}

@keyframes cargaRealHorsePulse {
  from { filter: drop-shadow(0 0 3px rgba(255,249,231,.86)) drop-shadow(0 0 8px rgba(255,124,36,.74)) drop-shadow(0 0 14px rgba(255,56,18,.52)); }
