}

@keyframes cargaRealParticleFloat {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) rotate(var(--particle-rotation, 0deg)) scale(.42);
  }
  9% {
    opacity: var(--particle-opacity, .82);
  }
  54% {
    opacity: .58;
  }
  78% {
    opacity: .28;
  }
  100% {
    opacity: 0;
    transform:
      translate(calc(-50% + var(--drift-x, 0%)), calc(-50% + var(--drift-y, 0%)))
      rotate(calc(var(--particle-rotation, 0deg) + 95deg))
      scale(1.32);
  }
}

@media (prefers-reduced-motion: reduce) {
  .carga-real-horse,
  .carga-real-particle { animation-duration: 1ms !important; }
}



