/* =========================================================
   ROK v399.x · EFECTO VISUAL DE ATURDIMIENTO EN ÓRBITA
   Estrellas amarillas girando sobre la cabeza de la invocación.
   Muestra 1 a 5 estrellas según las fases restantes de aturdimiento.
   ========================================================= */
.unit-protected-icons-layer {
  overflow: visible !important;
}

.unit-stun-orbit-fx {
  position: absolute;
  left: 50%;
  top: -36%;
  width: 108%;
  min-width: 42px;
  max-width: 76px;
  height: 56%;
  min-height: 24px;
  max-height: 44px;
  transform: translateX(-50%);
  transform-origin: 50% 50%;
  pointer-events: none;
  z-index: 39;
  animation: rokStunOrbitSpin 2.4s linear infinite;
  animation-delay: var(--stun-spin-delay, 0ms);
  filter: none !important;
  -webkit-filter: none !important;
}

.unit-stun-orbit-star {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%) scale(var(--stun-star-scale, 1));
  transform-origin: center center;
  display: block;
  font-size: clamp(7px, 0.57vw, 11px);
  line-height: 1;
  color: #ffd84d;
  text-shadow:
    0 0 2px rgba(255, 250, 205, 0.95),
    0 0 6px rgba(255, 214, 79, 0.95),
    0 0 12px rgba(255, 183, 0, 0.85);
  animation: rokStunStarTwinkle 1.1s ease-in-out infinite;
  animation-delay: var(--stun-star-twinkle-delay, 0ms);
}

@keyframes rokStunOrbitSpin {
  0% {
    transform: translateX(-50%) rotate(0deg);
  }
  100% {
    transform: translateX(-50%) rotate(360deg);
  }
}

@keyframes rokStunStarTwinkle {
  0%, 100% {
    opacity: 0.92;
    filter: brightness(1) saturate(1);
  }
  50% {
    opacity: 1;
    filter: brightness(1.18) saturate(1.18);
  }
}


/* =========================================================
   ROK v399.x · EFECTO VISUAL DE QUEMADURA SOBRE INVOCACIÓN
   Fueguitos persistentes con secuencia 1-2-3 y reaparición por zonas.
   Máximo 5 llamitas según las fases restantes del factor.
   ========================================================= */
.unit-burn-fx {
  position: absolute;
  left: 50%;
  top: -10%;
  width: 88%;
  height: 96%;
  transform: translateX(-50%);
  pointer-events: none;
  z-index: 38;
  overflow: visible;
}

.unit-burn-flame {
  position: absolute;
  left: 50%;
  top: 50%;
  width: clamp(7px, 0.57vw, 11px);
  height: clamp(9px, 0.74vw, 14px);
  transform: translate(-50%, -50%);
  opacity: 0;
  pointer-events: none;
  filter:
    drop-shadow(0 0 1px rgba(255, 243, 196, .14))
    drop-shadow(0 0 3px rgba(255, 153, 42, .18));
  animation: burnFlameTeleportCycle 6s linear infinite;
  animation-delay: var(--burn-teleport-delay, 0ms);
  will-change: left, top, opacity;
}

.unit-burn-frame {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.unit-burn-frame-1,
.unit-burn-frame-2,
.unit-burn-frame-3 {
  animation-duration: .54s;
  animation-timing-function: steps(1, end);
  animation-iteration-count: infinite;
  animation-delay: var(--burn-frame-delay, 0ms);
}

.unit-burn-frame-1 { animation-name: burnFrameCycle1; }
.unit-burn-frame-2 { animation-name: burnFrameCycle2; }
.unit-burn-frame-3 { animation-name: burnFrameCycle3; }

@keyframes burnFrameCycle1 {
  0%, 32.99% { opacity: .50; visibility: visible; }
  33%, 100% { opacity: 0; visibility: hidden; }
}

@keyframes burnFrameCycle2 {
  0%, 32.99% { opacity: 0; visibility: hidden; }
  33%, 65.99% { opacity: .50; visibility: visible; }
  66%, 100% { opacity: 0; visibility: hidden; }
}

@keyframes burnFrameCycle3 {
  0%, 65.99% { opacity: 0; visibility: hidden; }
  66%, 100% { opacity: .50; visibility: visible; }
}

@keyframes burnFlameTeleportCycle {
  0%, 2% {
    left: var(--burn-p1-x, 50%);
    top: var(--burn-p1-y, 50%);
    opacity: 0;
  }
  4%, 25% {
    left: var(--burn-p1-x, 50%);
    top: var(--burn-p1-y, 50%);
    opacity: 1;
  }
