  animation-timing-function: ease-out !important;
  animation-fill-mode: both !important;
}
@keyframes gloriaRestoreFxFadeV410 {
  0% { opacity: 0; }
  7% { opacity: 1; }
  84% { opacity: 1; }
  100% { opacity: 0; }
}
@keyframes gloriaGroundGlowV410 {
  0% { opacity: 0; transform: scaleX(.18) scaleY(.08); }
  28% { opacity: .94; transform: scaleX(.88) scaleY(.34); }
  78% { opacity: .58; transform: scaleX(1.02) scaleY(.42); }
  100% { opacity: 0; transform: scaleX(1.12) scaleY(.50); }
}
@keyframes gloriaRayTravelV410 {
  0% {
    opacity: 0;
    transform: translate(var(--gloria-ray-drift, 0%), 26%) rotate(var(--gloria-ray-tilt, 0deg)) scaleX(.42) scaleY(.16);
    filter: blur(1.8px);
  }
  16% {
    opacity: .88;
    filter: blur(.35px);
  }
  58% {
    opacity: .96;
    transform: translate(calc(var(--gloria-ray-drift, 0%) * .35), -16%) rotate(var(--gloria-ray-tilt, 0deg)) scaleX(.92) scaleY(.94);
    filter: blur(0);
  }
  100% {
    opacity: 0;
    transform: translate(calc(var(--gloria-ray-drift, 0%) * -0.45), -92%) rotate(var(--gloria-ray-tilt, 0deg)) scaleX(.64) scaleY(1.18);
    filter: blur(1.15px);
  }
}
@keyframes gloriaSparkTravelV410 {
  0% { opacity: 0; transform: translate(0, 8px) scale(.22); }
  20% { opacity: 1; }
  100% { opacity: 0; transform: translate(var(--gloria-spark-drift, 0px), -44px) scale(1.12); }
}

.healing-factor-cell-fx-v410 {
