  mix-blend-mode: screen;
}

.celestial-lamp-spark-burst {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 180%;
  height: 180%;
  transform: translate(-50%, -50%);
  opacity: 0;
  background:
    radial-gradient(circle at 18% 62%, #fff9c8 0 1.2%, transparent 2.2%),
    radial-gradient(circle at 34% 29%, #ffd857 0 1.5%, transparent 2.5%),
    radial-gradient(circle at 56% 18%, #fffdf0 0 1.1%, transparent 2.1%),
    radial-gradient(circle at 76% 36%, #ffd44d 0 1.5%, transparent 2.6%),
    radial-gradient(circle at 83% 68%, #fff7b5 0 1.2%, transparent 2.3%),
    radial-gradient(circle at 47% 82%, #ffd34a 0 1.4%, transparent 2.5%);
  filter: drop-shadow(0 0 5px #ffd34a);
}

.celestial-lamp-sprite {
  position: absolute;
  left: 50%;
  bottom: -10%;
  width: 92%;
  height: 148%;
  object-fit: contain;
  transform: translateX(-50%);
  transform-origin: 50% 100%;
  filter: drop-shadow(0 5px 6px rgba(0,0,0,.68)) drop-shadow(0 0 8px rgba(255,211,70,.62));
