@keyframes tentorouCellFlash {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.18); }
  22% { opacity: 1; transform: translate(-50%, -50%) scale(.76); }
  68% { opacity: .72; transform: translate(-50%, -50%) scale(1.12); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.46); }
