/* Etapa 4: la apertura comunica la mejor rareza del pack sin alterar
   la secuencia física del sobre. Básicas 1-3 no reciben efecto especial. */
.booster-opening-view.booster-reveal-tier-mid .booster-opening-effects {
  opacity: .62;
  filter: saturate(1.12);
}
.booster-opening-view.booster-reveal-tier-mid .booster-opening-effects i {
  width: 5px;
  height: 5px;
  box-shadow: 0 0 11px rgba(198,118,255,.78), 0 0 19px rgba(255,198,104,.28);
}
.booster-opening-view.booster-reveal-tier-high::before,
.booster-opening-view.booster-reveal-tier-legendary::before {
  content: "";
  position: absolute;
  inset: 8% 18%;
  z-index: 0;
  pointer-events: none;
  border-radius: 50%;
  opacity: 0;
  background: radial-gradient(circle, rgba(255,224,137,.28), rgba(177,86,255,.20) 30%, transparent 67%);
  animation: boosterOpeningHighAura 1.8s ease-out .55s both;
}
.booster-opening-view.booster-reveal-tier-legendary::before {
  inset: 3% 10%;
  background: radial-gradient(circle, rgba(255,244,177,.52), rgba(255,173,70,.28) 25%, rgba(179,77,255,.25) 45%, transparent 70%);
  animation: boosterOpeningLegendaryAura 2.25s ease-out .42s both;
}
.booster-opening-view.booster-reveal-tier-high .booster-opening-effects {
  opacity: .95;
  filter: saturate(1.35) brightness(1.12);
}
.booster-opening-view.booster-reveal-tier-legendary .booster-opening-effects {
  opacity: 1;
  filter: saturate(1.55) brightness(1.25);
}
@keyframes boosterOpeningHighAura {
  0% { opacity:0; transform:scale(.48); filter:blur(5px) brightness(1.8); }
  34% { opacity:.9; }
  100% { opacity:.22; transform:scale(1.2); filter:blur(0) brightness(1); }
}
@keyframes boosterOpeningLegendaryAura {
  0% { opacity:0; transform:scale(.28) rotate(-5deg); filter:blur(7px) brightness(2.4); }
  24% { opacity:1; }
  58% { opacity:.8; filter:blur(1px) brightness(1.5); }
  100% { opacity:.30; transform:scale(1.34) rotate(4deg); filter:blur(0) brightness(1); }
}

/* Efecto individual al revelarse: 4-6 medio, 7-9 fuerte, Legendaria especial. */
.booster-reveal-card.rarity-singular::before,
.booster-reveal-card.rarity-infrequent::before,
.booster-reveal-card.rarity-unusual::before,
.booster-reveal-card.rarity-strange::before,
.booster-reveal-card.rarity-mythic::before,
.booster-reveal-card.rarity-legendary::before {
  content: "";
  position: absolute;
  inset: -7px;
  z-index: -1;
  pointer-events: none;
  border-radius: 13px;
  opacity: 0;
}
.booster-reveal-card.rarity-singular::before,
.booster-reveal-card.rarity-infrequent::before,
.booster-reveal-card.rarity-unusual::before {
  background: radial-gradient(ellipse at 50% 45%, rgba(184,101,255,.32), transparent 68%);
  animation: boosterMidCardSpawn .9s ease-out calc(var(--booster-card-index,0) * 85ms) both;
}
.booster-reveal-card.rarity-strange::before,
.booster-reveal-card.rarity-mythic::before {
  inset: -11px;
  background: radial-gradient(ellipse at 50% 45%, rgba(255,215,119,.40), rgba(171,82,255,.26) 42%, transparent 72%);
  animation: boosterHighCardSpawn 1.15s ease-out calc(var(--booster-card-index,0) * 85ms) both;
}
.booster-reveal-card.rarity-legendary::before {
  inset: -16px;
  background: radial-gradient(ellipse at 50% 45%, rgba(255,240,165,.62), rgba(255,176,75,.36) 30%, rgba(172,74,255,.34) 54%, transparent 75%);
  animation: boosterLegendaryCardSpawn 1.5s ease-out calc(var(--booster-card-index,0) * 85ms) both;
