@keyframes boosterMidCardSpawn {
  0% { opacity:0; transform:scale(.68); filter:blur(5px); }
  42% { opacity:.8; }
  100% { opacity:.18; transform:scale(1.08); filter:blur(0); }
}
@keyframes boosterHighCardSpawn {
  0% { opacity:0; transform:scale(.48); filter:blur(7px) brightness(2); }
  34% { opacity:1; }
  100% { opacity:.28; transform:scale(1.13); filter:blur(0) brightness(1); }
}
@keyframes boosterLegendaryCardSpawn {
  0% { opacity:0; transform:scale(.32) rotate(-3deg); filter:blur(8px) brightness(2.7); }
