   R.O.K Lite v460 · Rarezas de booster · foil recortado al skin real
   ========================================================================== */

/* Se anulan por completo los patrones v458 que cubrían toda la carta. */
.booster-reveal-card .booster-card-rarity-foil,
.booster-reveal-card .booster-card-rarity-pattern,
.booster-reveal-card .booster-card-rarity-aura,
.booster-reveal-card .booster-card-rarity-particles,
.booster-reveal-card .booster-card-rarity-flare,
.booster-reveal-card::before {
  display: none !important;
  content: none !important;
}

/* El foil real es una copia del PNG .card-skin. Como ese archivo solo tiene
   píxeles visibles en el marco/zona inferior, el reflejo NO invade el arte. */
.booster-rarity-skin-foil {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: fill !important;
  z-index: 22 !important;
  pointer-events: none !important;
  border-radius: inherit !important;
  mix-blend-mode: screen !important;
}

/* Poco ordinaria / Extra ordinaria: foil básico limpio, únicamente en skin. */
.booster-rarity-skin-foil-basic {
  opacity: .66;
  filter: brightness(1.72) contrast(1.05) saturate(1.22);
  -webkit-mask-image: linear-gradient(116deg,
    transparent 0%, transparent 31%,
    rgba(0,0,0,.54) 41%, #000 49%, rgba(0,0,0,.62) 57%,
    transparent 69%, transparent 100%);
  mask-image: linear-gradient(116deg,
    transparent 0%, transparent 31%,
    rgba(0,0,0,.54) 41%, #000 49%, rgba(0,0,0,.62) 57%,
    transparent 69%, transparent 100%);
  -webkit-mask-size: 260% 100%;
  mask-size: 260% 100%;
  animation: boosterSkinFoilBasic 2.65s ease-in-out infinite;
}
.booster-reveal-card.rarity-uncommon .booster-rarity-skin-foil-basic {
  opacity: .48;
  animation-duration: 3.2s;
}
.booster-reveal-card.rarity-extraordinary .booster-rarity-skin-foil-basic {
  opacity: .68;
  animation-duration: 2.7s;
}

/* Singular / Infrecuente / Inhabitual: segundo reflejo fragmentado como foil
   físico, hecho de pequeños destellos adyacentes que cruzan el propio skin. */
.booster-rarity-skin-foil-spark {
  opacity: .86;
  filter: brightness(2.15) contrast(1.12) saturate(1.36);
  -webkit-mask-image:
    radial-gradient(ellipse at 12% 56%, transparent 0 3%, #000 4% 6%, transparent 7% 100%),
    radial-gradient(ellipse at 31% 43%, transparent 0 2%, #000 3% 5%, transparent 6% 100%),
    radial-gradient(ellipse at 49% 58%, transparent 0 3%, #000 4% 7%, transparent 8% 100%),
    radial-gradient(ellipse at 67% 45%, transparent 0 2%, #000 3% 5%, transparent 6% 100%),
    radial-gradient(ellipse at 86% 57%, transparent 0 3%, #000 4% 6%, transparent 7% 100%),
    linear-gradient(108deg, transparent 0 36%, rgba(0,0,0,.24) 42%, #000 50%, rgba(0,0,0,.28) 58%, transparent 66% 100%);
  mask-image:
    radial-gradient(ellipse at 12% 56%, transparent 0 3%, #000 4% 6%, transparent 7% 100%),
    radial-gradient(ellipse at 31% 43%, transparent 0 2%, #000 3% 5%, transparent 6% 100%),
    radial-gradient(ellipse at 49% 58%, transparent 0 3%, #000 4% 7%, transparent 8% 100%),
    radial-gradient(ellipse at 67% 45%, transparent 0 2%, #000 3% 5%, transparent 6% 100%),
    radial-gradient(ellipse at 86% 57%, transparent 0 3%, #000 4% 6%, transparent 7% 100%),
    linear-gradient(108deg, transparent 0 36%, rgba(0,0,0,.24) 42%, #000 50%, rgba(0,0,0,.28) 58%, transparent 66% 100%);
  -webkit-mask-size: 180% 130%,180% 130%,180% 130%,180% 130%,180% 130%,250% 100%;
  mask-size: 180% 130%,180% 130%,180% 130%,180% 130%,180% 130%,250% 100%;
  animation: boosterSkinFoilSpark 1.95s ease-in-out infinite;
}
.booster-reveal-card.rarity-singular .booster-rarity-skin-foil-spark {
  opacity: .68;
  animation-duration: 2.35s;
}
.booster-reveal-card.rarity-infrequent .booster-rarity-skin-foil-spark {
  opacity: .82;
  animation-duration: 2.05s;
}
.booster-reveal-card.rarity-unusual .booster-rarity-skin-foil-spark {
  opacity: .94;
  animation-duration: 1.78s;
}

/* Extraña/Mítica/Legendaria: el foil sigue viviendo en el skin, pero aquí sí
   añadimos luces translúcidas que recorren el conjunto de la carta de abajo
   hacia arriba, sin tapar el arte. */
.booster-rarity-high-streaks {
  position: absolute;
  inset: 0;
  z-index: 21;
  pointer-events: none;
  overflow: hidden;
  border-radius: inherit;
  opacity: .42;
  mix-blend-mode: screen;
  background:
    radial-gradient(ellipse at 18% 112%, rgba(255,86,211,.00) 0 28%, rgba(255,86,211,.34) 38%, rgba(255,86,211,0) 55%),
    radial-gradient(ellipse at 48% 118%, rgba(71,228,255,0) 0 29%, rgba(71,228,255,.34) 40%, rgba(71,228,255,0) 57%),
    radial-gradient(ellipse at 78% 110%, rgba(255,218,103,0) 0 28%, rgba(255,218,103,.32) 39%, rgba(255,218,103,0) 56%);
  background-size: 46% 72%, 48% 76%, 44% 70%;
  background-repeat: no-repeat;
  background-position: 0 128%, 46% 136%, 100% 124%;
  animation: boosterHighLightRise 3.2s linear infinite;
}
.booster-reveal-card.rarity-strange .booster-rarity-high-streaks { opacity: .34; animation-duration: 3.5s; }
.booster-reveal-card.rarity-mythic .booster-rarity-high-streaks { opacity: .48; animation-duration: 2.85s; }
.booster-reveal-card.rarity-legendary .booster-rarity-high-streaks { opacity: .58; animation-duration: 2.35s; }

/* Halo exterior solo para las tres rarezas altas. */
.booster-rarity-outer-glow {
  position: absolute;
  left: -6px;
  right: -6px;
  top: -6px;
  bottom: 27px;
  z-index: -1;
  pointer-events: none;
  border-radius: 12px;
  opacity: .66;
  box-shadow: 0 0 14px rgba(194,117,255,.20), 0 0 24px rgba(82,211,255,.14);
  animation: boosterOuterGlow 1.9s ease-in-out infinite alternate;
}
.booster-reveal-card.rarity-strange .booster-rarity-outer-glow {
  box-shadow: 0 0 13px rgba(173,101,255,.24), 0 0 24px rgba(77,204,255,.12);
}
.booster-reveal-card.rarity-mythic .booster-rarity-outer-glow {
  opacity: .84;
  box-shadow: 0 0 15px rgba(255,205,118,.28), 0 0 30px rgba(96,226,255,.16), 0 0 38px rgba(184,96,255,.13);
}
.booster-reveal-card.rarity-legendary .booster-rarity-outer-glow {
  opacity: 1;
  box-shadow: 0 0 17px rgba(255,220,137,.36), 0 0 34px rgba(255,169,88,.22), 0 0 48px rgba(177,89,255,.20), 0 0 56px rgba(76,220,255,.12);
}

/* Legendaria: borde exterior iridiscente independiente del skin. */
.booster-rarity-legendary-border {
  position: absolute;
  left: -4px;
  right: -4px;
  top: -4px;
  bottom: 25px;
  z-index: 24;
  pointer-events: none;
  border-radius: 11px;
  padding: 2px;
  background: linear-gradient(120deg,
    rgba(255,229,142,.95), rgba(255,113,207,.78), rgba(91,229,255,.88),
    rgba(169,104,255,.88), rgba(255,205,104,.96), rgba(255,229,142,.95));
  background-size: 320% 100%;
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  animation: boosterLegendaryBorderFlow 2.4s linear infinite;
}

/* Legendaria: partículas FUERA de la carta, irradiando hacia arriba. */
.booster-rarity-legendary-particles {
  position: absolute;
  left: -13%;
  right: -13%;
  top: -18%;
  bottom: 22px;
  z-index: 23;
  pointer-events: none;
  overflow: visible;
  opacity: .88;
  background:
    radial-gradient(circle at 12% 82%, rgba(255,236,168,.95) 0 1.4px, transparent 2.5px),
    radial-gradient(circle at 25% 92%, rgba(105,236,255,.90) 0 1.7px, transparent 2.8px),
    radial-gradient(circle at 41% 86%, rgba(224,126,255,.88) 0 1.5px, transparent 2.6px),
    radial-gradient(circle at 58% 94%, rgba(255,199,105,.95) 0 1.9px, transparent 3px),
    radial-gradient(circle at 72% 84%, rgba(115,228,255,.88) 0 1.5px, transparent 2.6px),
    radial-gradient(circle at 88% 91%, rgba(255,143,216,.86) 0 1.6px, transparent 2.7px);
  background-size: 100% 100%;
  animation: boosterLegendaryParticlesRise 2.05s ease-out infinite;
}

/* Las rarezas no deben alterar el tamaño de las cartas. */
.booster-reveal-card.rarity-ordinary .booster-reveal-card-visual,
.booster-reveal-card.rarity-uncommon .booster-reveal-card-visual,
.booster-reveal-card.rarity-extraordinary .booster-reveal-card-visual,
.booster-reveal-card.rarity-singular .booster-reveal-card-visual,
.booster-reveal-card.rarity-infrequent .booster-reveal-card-visual,
.booster-reveal-card.rarity-unusual .booster-reveal-card-visual,
.booster-reveal-card.rarity-strange .booster-reveal-card-visual,
.booster-reveal-card.rarity-mythic .booster-reveal-card-visual,
.booster-reveal-card.rarity-legendary .booster-reveal-card-visual {
  filter: none !important;
}

@keyframes boosterSkinFoilBasic {
  0%, 9% { -webkit-mask-position: 122% 50%; mask-position: 122% 50%; opacity: .10; }
  22% { opacity: .44; }
  49% { opacity: .78; }
  78% { opacity: .44; }
  92%, 100% { -webkit-mask-position: -52% 50%; mask-position: -52% 50%; opacity: .10; }
}
@keyframes boosterSkinFoilSpark {
  0% {
    -webkit-mask-position: 122% 65%, 105% 35%, 132% 60%, 116% 42%, 128% 66%, 122% 50%;
    mask-position: 122% 65%, 105% 35%, 132% 60%, 116% 42%, 128% 66%, 122% 50%;
    opacity: .18;
  }
  36% { opacity: .88; }
  68% { opacity: .56; }
  100% {
    -webkit-mask-position: -38% 45%, -62% 70%, -30% 42%, -52% 66%, -42% 38%, -52% 50%;
    mask-position: -38% 45%, -62% 70%, -30% 42%, -52% 66%, -42% 38%, -52% 50%;
    opacity: .16;
  }
}
@keyframes boosterHighLightRise {
  0% { background-position: 0 130%, 46% 138%, 100% 128%; opacity: .12; }
  18% { opacity: .44; }
  70% { opacity: .38; }
  100% { background-position: 0 -62%, 46% -74%, 100% -58%; opacity: .08; }
}
@keyframes boosterOuterGlow {
  from { transform: scale(.994); filter: brightness(.92); }
  to { transform: scale(1.008); filter: brightness(1.18); }
}
@keyframes boosterLegendaryBorderFlow {
  from { background-position: 0% 50%; }
  to { background-position: 320% 50%; }
}
@keyframes boosterLegendaryParticlesRise {
  0% { transform: translateY(16%) scale(.96); opacity: 0; }
  24% { opacity: .88; }
  72% { opacity: .72; }
  100% { transform: translateY(-28%) scale(1.05); opacity: 0; }
}


